action.command:
cd /workspace && cat > /tmp/resolve.py << 'EOF'
import json,sys
d=json.load(open('contracts/openapi.contract.json'))
schemas=d['components']['schemas']
def resolve(node, depth=0):
    if depth>20: return node
    if isinstance(node,dict):
        if '$ref' in node and len(node)==1:
            ref=node['$ref']
            if ref.startswith('#/components/schemas/'):
                return resolve(schemas[ref.split('/')[-1]],depth+1)
            return node
        return {k:resolve(v,depth+1) for k,v in node.items()}
    if isinstance(node,list):
        return [resolve(x,depth+1) for x in node]
    return node

def compact(node,indent=0):
    # produce compact readable: fields with type and required
    pass

for p,methods in d['paths'].items():
    for m,op in methods.items():
        if m not in ['get','post','put','patch','delete']: continue
        print('='*90)
        print(f'{m.upper()} {p}  operationId={op.get("operationId")}')
        desc=(op.get('description') or op.get('summary') or '').strip()
        if desc: print('DESC:',desc[:400])
        # params
        for pr in op.get('parameters',[]):
            pr=resolve(pr)
            print(f'  PARAM {pr.get("name")} (in={pr.get("in")}, required={pr.get("required")})')
        rb=op.get('requestBody')
        if rb:
            rb=resolve(rb)
            content=rb.get('content',{})
            for ct,media in content.items():
                schema=media.get('schema',{})
                print(f'  REQBODY [{ct}]:')
                print('   ', json.dumps(schema))
        # responses
        for code,r in op.get('responses',{}).items():
            r=resolve(r)
            content=r.get('content',{})
            print(f'  RESP {code}:', r.get('description',''))
            for ct,media in content.items():
                schema=media.get('schema',{})
                print(f'    [{ct}] schema:', json.dumps(schema))
EOF
python3 /tmp/resolve.py > /tmp/ops_resolved.txt 2>&1
wc -l /tmp/ops_resolved.txt
sed -n '1,150p' /tmp/ops_resolved.txt

