def fields(schema,depth=0,seen=None):
    seen=seen or set()
    if depth>12: return '<too deep>'
    if isinstance(schema,dict):
        if '$ref' in schema and len(schema)==1:
            name=schema['$ref'].split('/')[-1]
            if name in seen: return f'<ref {name}>'
            return fields(schemas.get(name,{}),depth+1,seen|{name})
        if 'allOf' in schema:
            out={}
            for s in schema['allOf']:
                out.update(fields(s,depth+1,seen) if isinstance(fields(s,depth+1,seen),dict) else {})
            # merge properties of this schema too
            if 'properties' in schema or 'required' in schema:
                pass
            return out
        if schema.get('type')=='object' or 'properties' in schema:
            out={}
            props=schema.get('properties',{})
            for k,v in props.items():
                t=v.get('type') or ('object' if 'properties' in v else ('ref' if '$ref' in v else ''))
                if '$ref' in v: t='ref:'+v['$ref'].split('/')[-1]
                if 'allOf' in v:
                    inner=fields(v,depth+1,seen)
                    if isinstance(inner,dict): t=inner
                    else: t='allof'
                if v.get('type')=='array':
                    items=v.get('items',{})
                    it=items.get('type') or ('ref:'+items['$ref'].split('/')[-1] if '$ref' in items else 'obj')
                    t=f'array<{it}>'
                out[k]=t
            return out
        if schema.get('type')=='array':
            items=schema.get('items',{})
            return f'array<{items.get("type") or (items.get("$ref","").split("/")[-1] if "$ref" in items else "obj")}>'
        return schema.get('type','?')
    return str(schema)

for p,methods in d['paths'].items():
