        if m not in ['get','post','put','patch','delete']: continue
        print('='*80)
        print(f'{m.upper()} {p}  ::  {op.get("operationId")}')
        rb=op.get('requestBody',{})
        content=rb.get('content',{}) if rb else {}
        for ct,media in content.items():
            sch=media.get('schema',{})
            print(f'  REQ {ct}: required={sch.get("required",[])}')
            f=fields(sch)
            print('   ',json.dumps(f))
        for code,r in op.get('responses',{}).items():
            content=r.get('content',{})
            for ct,media in content.items():
                sch=media.get('schema',{})
                # find the 'data' object if present
                data=sch.get('properties',{}).get('data',{})
                if data:
                    print(f'  RESP {code} data: required={data.get("required",[])}')
