package audit

import (
	"context"
	"fmt"
	"sync"
	"sync/atomic"
	"time"

	"go.mongodb.org/mongo-driver/bson"
	"go.mongodb.org/mongo-driver/mongo"
	"go.mongodb.org/mongo-driver/mongo/options"
)

// Entry is a single audit record.
type Entry struct {
	ActorID    string                 `json:"actorId"`
	Role       string                 `json:"role"`
	Action     string                 `json:"action"`
	EntityType string                 `json:"entityType"`
	EntityID   string                 `json:"entityId"`
	At         time.Time              `json:"at"`
	Success    bool                   `json:"success"`
	Outcome    string                 `json:"outcome,omitempty"`
	Changes    map[string]interface{} `json:"changes,omitempty"`
	Query      string                 `json:"query,omitempty"`
}

// Store persists audit entries and realtime events in MongoDB.
type Store struct {
	col   *mongo.Collection
	evts  *mongo.Collection
	seq   atomic.Int64
	once  sync.Once
}

func New(db *mongo.Database) *Store {
	return &Store{
		col:  db.Collection("audit_log"),
		evts: db.Collection("realtime_events"),
	}
}

func (s *Store) ensureSeq(ctx context.Context) {
	s.once.Do(func() {
		// Initialize sequence cursor from the highest existing seq.
		var doc struct {
			Seq int64 `bson:"seq"`
		}
		opts := options.FindOne().SetSort(bson.D{{Key: "seq", Value: -1}})
		_ = s.evts.FindOne(ctx, bson.D{}, opts).Decode(&doc)
		s.seq.Store(doc.Seq)
	})
}

// Record appends an audit entry.
func (s *Store) Record(ctx context.Context, e Entry) {
	if e.At.IsZero() {
		e.At = time.Now().UTC()
	}
	go func() {
		ctx, cancel := context.WithTimeout(context.Background(), 3*time.Second)
		defer cancel()
		doc := bson.M{
			"actorId":    e.ActorID,
			"role":        e.Role,
			"action":      e.Action,
			"entityType":  e.EntityType,
			"entityId":    e.EntityID,
			"at":          e.At,
			"success":     e.Success,
			"outcome":     e.Outcome,
			"changes":     e.Changes,
			"query":       e.Query,
		}
		_, _ = s.col.InsertOne(ctx, doc)
	}()
}

// Event is a realtime event record.
type Event struct {
	Seq      int64                  `json:"seq"`
	Type     string                 `json:"type"`
	SampleID string                 `json:"sampleId,omitempty"`
	At       time.Time              `json:"at"`
	Data     map[string]interface{} `json:"data,omitempty"`
}

// Emit appends a realtime event.
func (s *Store) Emit(ctx context.Context, ev Event) {
	s.ensureSeq(ctx)
	ev.Seq = s.seq.Add(1)
	if ev.At.IsZero() {
		ev.At = time.Now().UTC()
	}
	go func() {
		ctx, cancel := context.WithTimeout(context.Background(), 3*time.Second)
		defer cancel()
		doc := bson.M{
			"seq":      ev.Seq,
			"type":     ev.Type,
			"sampleId": ev.SampleID,
			"at":       ev.At,
			"data":     ev.Data,
		}
		_, _ = s.evts.InsertOne(ctx, doc)
	}()
}

// AuditEntry is the response projection of an audit entry.
type AuditEntry struct {
	EntryID    string                 `json:"entryId"`
	ActorID    string                 `json:"actorId"`
	Role       string                 `json:"role"`
	Action     string                 `json:"action"`
	EntityType string                 `json:"entityType"`
	EntityID   string                 `json:"entityId"`
	At         time.Time              `json:"at"`
	Outcome    string                 `json:"outcome"`
	Success    bool                   `json:"success"`
	Changes    map[string]interface{} `json:"changes,omitempty"`
}

// Filter selects audit records.
type Filter struct {
	Query      string
	ActorID    string
	EntityType string
	EntityID   string
	Action     string
	Role       string
	Success    *bool
	FromTime   *time.Time
	ToTime     *time.Time
	Limit      int
	Offset     int
	Order      string
}

// Search returns matching audit entries.
func (s *Store) Search(ctx context.Context, f Filter) ([]AuditEntry, int64, error) {
	q := bson.D{}
	if f.Query != "" {
		q = append(q, bson.E{Key: "$text", Value: bson.M{"$search": f.Query}})
	}
	if f.ActorID != "" {
