			"actorId":   e.ActorID,
			"role":       e.Role,
			"action":     e.Action,
			"entityType": e.EntityType,
			"entityId":   e.EntityID,
			"at":         e.At,
			"success":    e.Success,
			"outcome":    e.Outcome,
			"changes":    e.Changes,
			"query":      e.Query,
		}
		_, _ = s.col.InsertOne(ctx, doc)
	}()
}

// Event is a realtime event record.
type Event struct {
	Seq      int64                  `json:"seq"`
	Type     string                 `json:"type"`
	SampleID string                 `json:"sampleId,omitempty"`
	At       time.Time              `json:"at"`
	Data     map[string]interface{} `json:"data,omitempty"`
}

// Emit appends a realtime event.
func (s *Store) Emit(ctx context.Context, ev Event) {
	s.ensureSeq(ctx)
	ev.Seq = s.seq.Add(1)
	if ev.At.IsZero() {
		ev.At = time.Now().UTC()
	}
	go func() {
		ctx, cancel := context.WithTimeout(context.Background(), 3*time.Second)
		defer cancel()
		doc := bson.M{
			"seq":      ev.Seq,
			"type":     ev.Type,
			"sampleId": ev.SampleID,
			"at":       ev.At,
			"data":     ev.Data,
		}
		_, _ = s.evts.InsertOne(ctx, doc)
	}()
}

// AuditEntry is the response projection of an audit entry.
type AuditEntry struct {
	EntryID    string                 `json:"entryId"`
	ActorID    string                 `json:"actorId"`
	Role       string                 `json:"role"`
	Action     string                 `json:"action"`
	EntityType string                 `json:"entityType"`
	EntityID   string                 `json:"entityId"`
	At         time.Time              `json:"at"`
	Outcome    string                 `json:"outcome"`
	Success    bool                   `json:"success"`
	Changes    map[string]interface{} `json:"changes,omitempty"`
}

// Filter selects audit records.
type Filter struct {
	Query      string
	ActorID    string
	EntityType string
	EntityID   string
	Action     string
	Role       string
	Success    *bool
	FromTime   *time.Time
	ToTime     *time.Time
	Limit      int
	Offset     int
	Order      string
}

// Search returns matching audit entries.
func (s *Store) Search(ctx context.Context, f Filter) ([]AuditEntry, int64, error) {
	q := bson.D{}
	if f.Query != "" {
		q = append(q, bson.E{Key: "$text", Value: bson.M{"$search": f.Query}})
	}
	if f.ActorID != "" {
		q = append(q, bson.E{Key: "actorId", Value: f.ActorID})
	}
	if f.EntityType != "" {
		q = append(q, bson.E{Key: "entityType", Value: f.EntityType})
	}
	if f.EntityID != "" {
		q = append(q, bson.E{Key: "entityId", Value: f.EntityID})
	}
	if f.Action != "" {
		q = append(q, bson.E{Key: "action", Value: f.Action})
	}
	if f.Role != "" {
		q = append(q, bson.E{Key: "role", Value: f.Role})
	}
	if f.Success != nil {
		q = append(q, bson.E{Key: "success", Value: *f.Success})
	}
	if f.FromTime != nil {
		q = append(q, bson.E{Key: "at", Value: bson.M{"$gte": *f.FromTime}})
	}
	if f.ToTime != nil {
		q = append(q, bson.E{Key: "at", Value: bson.M{"$lte": *f.ToTime}})
	}
	limit := f.Limit
	if limit <= 0 || limit > 200 {
		limit = 50
	}
	if f.Offset < 0 {
		f.Offset = 0
	}
	total, err := s.col.CountDocuments(ctx, q)
	if err != nil {
		return nil, 0, err
	}
	opts := options.Find().SetLimit(int64(limit)).SetSkip(int64(f.Offset))
	if f.Order == "asc" {
		opts.SetSort(bson.D{{Key: "at", Value: 1}})
	} else {
		opts.SetSort(bson.D{{Key: "at", Value: -1}})
	}
	cur, err := s.col.Find(ctx, q, opts)
	if err != nil {
		return nil, 0, err
	}
	defer cur.Close(ctx)
	var out []AuditEntry
	for cur.Next(ctx) {
		var raw struct {
			ID      interface{}            `bson:"_id"`
			ActorID string                 `bson:"actorId"`
			Role    string                 `bson:"role"`
			Action  string                 `bson:"action"`
			EType   string                 `bson:"entityType"`
			EID     string                 `bson:"entityId"`
			At      time.Time              `bson:"at"`
			Outcome string                 `bson:"outcome"`
			Success bool                   `bson:"success"`
			Changes map[string]interface{} `bson:"changes"`
		}
		if err := cur.Decode(&raw); err != nil {
			continue
		}
		out = append(out, AuditEntry{
			EntryID:    fmt.Sprintf("%v", raw.ID),
			ActorID:    raw.ActorID,
			Role:       raw.Role,
			Action:     raw.Action,
			EntityType: raw.EType,
			EntityID:   raw.EID,
			At:         raw.At,
			Outcome:    raw.Outcome,
			Success:    raw.Success,
			Changes:    raw.Changes,
		})
	}
	return out, total, nil
}

// Events returns realtime events since the given cursor.
func (s *Store) Events(ctx context.Context, since int64, limit int) ([]Event, int64, error) {
	if limit <= 0 || limit > 500 {
		limit = 100
	}
	opts := options.Find().SetLimit(int64(limit)).SetSort(bson.D{{Key: "seq", Value: 1}})
	cur, err := s.evts.Find(ctx, bson.M{"seq": bson.M{"$gt": since}}, opts)
	if err != nil {
		return nil, 0, err
	}
	defer cur.Close(ctx)
	var out []Event
	var maxSeq int64 = since
	for cur.Next(ctx) {
		var raw struct {
			Seq      int64                  `bson:"seq"`
			Type     string                 `bson:"type"`
			SampleID string                 `bson:"sampleId"`
			At       time.Time              `bson:"at"`
			Data     map[string]interface{} `bson:"data"`
		}
		if err := cur.Decode(&raw); err != nil {
			continue
		}
		out = append(out, Event{Seq: raw.Seq, Type: raw.Type, SampleID: raw.SampleID, At: raw.At, Data: raw.Data})
		if raw.Seq > maxSeq {
			maxSeq = raw.Seq
		}
	}
	return out, maxSeq, nil
}

