package store

import (
	"context"
	"time"

	"github.com/google/uuid"
	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"
)

// Store coordinates Postgres persistence for the whole application.
type Store struct {
	PG *pgxpool.Pool
}

func New(pg *pgxpool.Pool) *Store {
	return &Store{PG: pg}
}

// ---------------------------------------------------------------------------
// Models
// ---------------------------------------------------------------------------

type Role string

const (
	RoleAdministrator         Role = "administrator"
	RoleDispatcher             Role = "dispatcher"
	RoleRequester              Role = "requester"
	RoleCollectionProfessional Role = "collection_professional"
	RoleDeliveryPartner        Role = "delivery_partner"
	RoleNodeHandler            Role = "node_handler"
	RoleLaboratoryTeam         Role = "laboratory_team"
)

func ValidRole(r string) bool {
	switch Role(r) {
	case RoleAdministrator, RoleDispatcher, RoleRequester, RoleCollectionProfessional,
		RoleDeliveryPartner, RoleNodeHandler, RoleLaboratoryTeam:
		return true
	}
	return false
}

type Certification struct {
	Code      string     `json:"code"`
	Active    bool       `json:"active"`
	ExpiresAt *time.Time `json:"expiresAt,omitempty"`
}

type User struct {
	UserID              uuid.UUID      `json:"userId"`
	Username            string         `json:"username"`
	Email               string         `json:"email,omitempty"`
	FullName            string         `json:"fullName,omitempty"`
	Phone               string         `json:"phone,omitempty"`
	Roles               []string       `json:"roles"`
	Qualifications      []string       `json:"qualifications"`
	Certifications      []Certification `json:"certifications"`
	Active              bool           `json:"active"`
	AssignedLocationID  *uuid.UUID     `json:"-"`
	WorkerAvailable     bool           `json:"-"`
	WorkerCapacityUnits int            `json:"-"`
}

type LocationFunction struct {
	CollectionPoint bool `json:"collection_point"`
	TransferPoint   bool `json:"transfer_point"`
	Hub             bool `json:"hub"`
	Laboratory      bool `json:"laboratory"`
}

type Location struct {
	LocationID       uuid.UUID       `json:"locationId"`
	Name             string          `json:"name"`
	Lat              float64         `json:"-"`
	Lon              float64         `json:"-"`
	CoverageKm       float64         `json:"coverageKm"`
	HandlingMinutes  int             `json:"handlingMinutes"`
	Active            bool            `json:"active"`
	Functions         LocationFunction `json:"functions"`
}

type Connection struct {
	ConnectionID  uuid.UUID `json:"connectionId"`
	FromLocation  uuid.UUID `json:"fromLocationId"`
	ToLocation    uuid.UUID `json:"toLocationId"`
	TravelMinutes int       `json:"travelMinutes"`
	CostUnits     float64   `json:"costUnits"`
	Cooled        bool      `json:"cooled"`
	Active        bool      `json:"active"`
}

type Capacity struct {
	ResourceID          uuid.UUID `json:"resourceId"`
	CapacityUnits       int       `json:"capacityUnits"`
	CooledCapacityUnits int       `json:"cooledCapacityUnits"`
	ReservedUnits       int       `json:"-"`
	CooledReservedUnits int       `json:"-"`
}

type SampleType struct {
	SampleTypeID              uuid.UUID   `json:"sampleTypeId"`
	Name                      string      `json:"name"`
	QualifiedCollectorRequired bool        `json:"qualifiedCollectorRequired"`
	RequiredQualification     string      `json:"requiredQualification"`
	ContainerType             string      `json:"containerType"`
	TemperatureMinC           *float64    `json:"temperatureMinC"`
	TemperatureMaxC           *float64    `json:"temperatureMaxC"`
	IncompatibleSampleTypes   []uuid.UUID `json:"incompatibleSampleTypes"`
	RequiresCooledRoute       bool        `json:"requiresCooledRoute"`
	BatchingAllowed           bool        `json:"batchingAllowed"`
}

// AssignmentKind enumerates assignment categories.
type AssignmentKind string

const (
	KindCollection AssignmentKind = "collection"
	KindTransport  AssignmentKind = "transport"
	KindNode       AssignmentKind = "node"
	KindLab        AssignmentKind = "laboratory"
)

type Assignment struct {
	AssignmentID        uuid.UUID `json:"assignmentId"`
	JourneyID           uuid.UUID `json:"-"`
	SampleID            uuid.UUID `json:"sampleId"`
	Kind                string    `json:"kind"`
	Sequence            int       `json:"sequence"`
	Status              string    `json:"status"`
	FromLocation        *uuid.UUID `json:"fromLocationId,omitempty"`
	ToLocation          *uuid.UUID `json:"toLocationId,omitempty"`
	WorkerID            *uuid.UUID `json:"workerId,omitempty"`
	OfferedWorkerID     *uuid.UUID `json:"offeredWorkerId,omitempty"`
	NodeID              *uuid.UUID `json:"nodeId,omitempty"`
	LaboratoryID        *uuid.UUID `json:"laboratoryId,omitempty"`
	Cooled              bool      `json:"cooled"`
}

// ============================================================================
// Users
// ============================================================================

// CreateUser persists a new user. Returns the stored user (without password).
func (s *Store) CreateUser(ctx context.Context, tx pgx.Tx, u *User, passwordHash string) error {
	if u.UserID == uuid.Nil {
		u.UserID = uuid.New()
	}
	_, err := tx.Exec(ctx, `INSERT INTO users
		(user_id, username, password_hash, email, full_name, phone, active, assigned_location_id)
		VALUES ($1,$2,$3,$4,$5,$6,$7,$8)`,
		u.UserID, u.Username, passwordHash, u.Email, u.FullName, u.Phone, u.Active, u.AssignedLocationID)
	if err != nil {
		return err
	}
	for _, r := range u.Roles {
		if _, err := tx.Exec(ctx, "INSERT INTO user_roles (user_id, role) VALUES ($1,$2)", u.UserID, r); err != nil {
			return err
		}
	}
	for _, q := range u.Qualifications {
		if _, err := tx.Exec(ctx, "INSERT INTO qualifications (user_id, code) VALUES ($1,$2)", u.UserID, q); err != nil {
			return err
		}
	}
	for _, c := range u.Certifications {
		cid := uuid.New()
		if _, err := tx.Exec(ctx, "INSERT INTO certifications (cert_id, user_id, code, active, expires_at) VALUES ($1,$2,$3,$4,$5)",
			cid, u.UserID, c.Code, c.Active, c.ExpiresAt); err != nil {
			return err
		}
	}
	return nil
}

func (s *Store) UserByUsername(ctx context.Context, username string) (*User, string, error) {
	row := s.PG.QueryRow(ctx, `SELECT user_id, username, password_hash, email, full_name, phone, active FROM users WHERE username=$1`, username)
	var u User
	var hash string
	var email, full, phone *string
	if err := row.Scan(&u.UserID, &u.Username, &hash, &email, &full, &phone, &u.Active); err != nil {
		return nil, "", err
	}
	if email != nil {
		u.Email = *email
	}
	if full != nil {
		u.FullName = *full
	}
	if phone != nil {
		u.Phone = *phone
	}
	if err := s.loadUserDetail(ctx, &u); err != nil {
		return nil, "", err
	}
	return &u, hash, nil
}

func (s *Store) UserByID(ctx context.Context, id uuid.UUID) (*User, error) {
	row := s.PG.QueryRow(ctx, `SELECT user_id, username, email, full_name, phone, active, assigned_location_id FROM users WHERE user_id=$1`, id)
	var u User
	var email, full, phone *string
	if err := row.Scan(&u.UserID, &u.Username, &email, &full, &phone, &u.Active, &u.AssignedLocationID); err != nil {
		return nil, err
	}
	if email != nil {
		u.Email = *email
	}
	if full != nil {
		u.FullName = *full
	}
	if phone != nil {
		u.Phone = *phone
	}
	if err := s.loadUserDetail(ctx, &u); err != nil {
		return nil, err
	}
	return &u, nil
}

func (s *Store) loadUserDetail(ctx context.Context, u *User) error {
	rows, err := s.PG.Query(ctx, "SELECT role FROM user_roles WHERE user_id=$1", u.UserID)
	if err != nil {
		return err
	}
	defer rows.Close()
	for rows.Next() {
		var r string
		_ = rows.Scan(&r)
		u.Roles = append(u.Roles, r)
	}
	qrows, err := s.PG.Query(ctx, "SELECT code FROM qualifications WHERE user_id=$1", u.UserID)
	if err != nil {
		return err
	}
	defer qrows.Close()
	for qrows.Next() {
		var c string
		_ = qrows.Scan(&c)
		u.Qualifications = append(u.Qualifications, c)
	}
	crows, err := s.PG.Query(ctx, "SELECT code, active, expires_at FROM certifications WHERE user_id=$1", u.UserID)
	if err != nil {
		return err
	}
	defer crows.Close()
	for crows.Next() {
		var c Certification
		_ = crows.Scan(&c.Code, &c.Active, &c.ExpiresAt)
		u.Certifications = append(u.Certifications, c)
	}
	return nil
}

// UserCount returns the number of users.
func (s *Store) UserCount(ctx context.Context) (int, error) {
	var n int
	err := s.PG.QueryRow(ctx, "SELECT count(*) FROM users").Scan(&n)
	return n, err
}

// HasAnyUsers reports whether any users exist.
func (s *Store) HasAnyUsers(ctx context.Context) (bool, error) {
	n, err := s.UserCount(ctx)
	return n > 0, err
}

