}

func (s *Store) UpdateLocation(ctx context.Context, tx pgx.Tx, id uuid.UUID, name string, lat, lon, coverage float64, handling int, fns LocationFunction) error {
	_, err := tx.Exec(ctx, `UPDATE locations SET name=$2, lat=$3, lon=$4, coverage_km=$5, handling_minutes=$6,
