	return &Connection{ConnectionID: id, FromLocation: from, ToLocation: to, TravelMinutes: travel, CostUnits: cost, Cooled: cooled, Active: active}, nil
}

func (s *Store) AllConnections(ctx context.Context) ([]*Connection, error) {
	rows, err := s.PG.Query(ctx, `SELECT connection_id, from_location_id, to_location_id, travel_minutes, cost_units, cooled, active FROM connections`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []*Connection
	for rows.Next() {
		var c Connection
		if err := rows.Scan(&c.ConnectionID, &c.FromLocation, &c.ToLocation, &c.TravelMinutes, &c.CostUnits, &c.Cooled, &c.Active); err != nil {
			return nil, err
		}
		out = append(out, &c)
	}
	return out, nil
}

func (s *Store) SetConnectionStatus(ctx context.Context, tx pgx.Tx, id uuid.UUID, active bool) error {
	_, err := tx.Exec(ctx, "UPDATE connections SET active=$2 WHERE connection_id=$1", id, active)
	return err
}

// ============================================================================
// Capacity
// ============================================================================

func (s *Store) GetCapacity(ctx context.Context, resourceID uuid.UUID) (*Capacity, error) {
	row := s.PG.QueryRow(ctx, `SELECT resource_id, capacity_units, cooled_capacity_units, reserved_units, cooled_reserved_units FROM capacity WHERE resource_id=$1`, resourceID)
	var c Capacity
	if err := row.Scan(&c.ResourceID, &c.CapacityUnits, &c.CooledCapacityUnits, &c.ReservedUnits, &c.CooledReservedUnits); err != nil {
		return nil, err
	}
	return &c, nil
}

// EnsureCapacity creates a capacity row if missing.
func (s *Store) EnsureCapacity(ctx context.Context, tx pgx.Tx, resourceID uuid.UUID, kind string) error {
	_, err := tx.Exec(ctx, `INSERT INTO capacity (resource_id, resource_kind) VALUES ($1,$2) ON CONFLICT (resource_id) DO NOTHING`, resourceID, kind)
	return err
}

func (s *Store) ConfigureCapacity(ctx context.Context, tx pgx.Tx, resourceID uuid.UUID, units, cooled int) (*Capacity, error) {
	_, err := tx.Exec(ctx, `INSERT INTO capacity (resource_id, resource_kind, capacity_units, cooled_capacity_units)
		VALUES ($1,'location',$2,$3) ON CONFLICT (resource_id)
		DO UPDATE SET capacity_units=EXCLUDED.capacity_units, cooled_capacity_units=EXCLUDED.cooled_capacity_units`,
		resourceID, units, cooled)
	if err != nil {
		return nil, err
	}
	return s.GetCapacity(ctx, resourceID)
}

// ============================================================================
// Laboratory acceptance
// ============================================================================

func (s *Store) ConfigureLabAcceptance(ctx context.Context, tx pgx.Tx, labID, sampleTypeID uuid.UUID, accepts bool) (uuid.UUID, error) {
	id := uuid.New()
	_, err := tx.Exec(ctx, `INSERT INTO laboratory_acceptance (acceptance_id, laboratory_id, sample_type_id, accepts)
		VALUES ($1,$2,$3,$4)
		ON CONFLICT (laboratory_id, sample_type_id) DO UPDATE SET accepts=EXCLUDED.accepts, acceptance_id=laboratory_acceptance.acceptance_id
		RETURNING acceptance_id`, id, labID, sampleTypeID, accepts)
	if err != nil {
		return uuid.Nil, err
	}
	var aid uuid.UUID
	_ = tx.QueryRow(ctx, "SELECT acceptance_id FROM laboratory_acceptance WHERE laboratory_id=$1 AND sample_type_id=$2", labID, sampleTypeID).Scan(&aid)
	if aid == uuid.Nil {
		aid = id
	}
	return aid, nil
}

func (s *Store) LabAccepts(ctx context.Context, labID, sampleTypeID uuid.UUID) (bool, error) {
	var accepts bool
	err := s.PG.QueryRow(ctx, "SELECT accepts FROM laboratory_acceptance WHERE laboratory_id=$1 AND sample_type_id=$2", labID, sampleTypeID).Scan(&accepts)
	return accepts, err
}

// AcceptingLabForSampleType returns IDs of active labs that accept the sample type.
func (s *Store) AcceptingLabs(ctx context.Context, sampleTypeID uuid.UUID) ([]uuid.UUID, error) {
	rows, err := s.PG.Query(ctx, `SELECT l.location_id FROM locations l
