		WHERE a.accepts=TRUE AND l.active=TRUE AND l.fn_laboratory=TRUE AND a.sample_type_id=$1`, sampleTypeID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []uuid.UUID
	for rows.Next() {
		var id uuid.UUID
		_ = rows.Scan(&id)
		out = append(out, id)
	}
	return out, nil
}

