// ============================================================================
// Samples & requests
// ============================================================================

type Sample struct {
	SampleID         uuid.UUID
	RequestID        uuid.UUID
	RequesterID      uuid.UUID
	SampleTypeID     uuid.UUID
	ContainerType    string
	TemperatureMinC  *float64
	TemperatureMaxC  *float64
	Incompatible      []uuid.UUID
	OriginType       string
	OriginLat        float64
	OriginLon        float64
	OriginNodeID     *uuid.UUID
	RequestedAt      time.Time
	DeliveryDeadline time.Time
	EarliestColl     *time.Time
	LatestColl       *time.Time
