		if err := rows.Scan(&sm.SampleID, &sm.RequestID, &sm.RequesterID, &sm.SampleTypeID, &sm.ContainerType, &sm.TemperatureMinC, &sm.TemperatureMaxC,
			&sm.Incompatible, &sm.OriginType, &sm.OriginLat, &sm.OriginLon, &sm.OriginNodeID, &sm.RequestedAt, &sm.DeliveryDeadline,
			&earliest, &latest, &sm.Status, &sm.Sealed, &sealedAt, &sm.CurrentHolderID, &sm.ActiveJourneyID,
