// AllWorkers returns users that hold a worker role.
func (s *Store) AllWorkers(ctx context.Context) ([]uuid.UUID, error) {
	rows, err := s.PG.Query(ctx, `SELECT DISTINCT u.user_id FROM users u JOIN user_roles r ON r.user_id=u.user_id
		WHERE r.role IN ('collection_professional','delivery_partner','node_handler','laboratory_team') AND u.active=TRUE`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []uuid.UUID
	for rows.Next() {
		var id uuid.UUID
		_ = rows.Scan(&id)
		out = append(out, id)
	}
	return out, nil
}

