type Handoff struct {
	HandoffID         uuid.UUID
	SampleID          uuid.UUID
	FromAssignmentID  uuid.UUID
	ToAssignmentID    uuid.UUID
	SenderID          uuid.UUID
	ReceiverID        uuid.UUID
