		FROM handoffs WHERE handoff_id=$1`, id)
	var h Handoff
	if err := row.Scan(&h.HandoffID, &h.SampleID, &h.FromAssignmentID, &h.ToAssignmentID, &h.SenderID, &h.ReceiverID,
		&h.Status, &h.SenderConfirmed, &h.ReceiverConfirmed, &h.SenderConfirmedAt, &h.ReceiverConfirmedAt, &h.InitiatedAt, &h.CompletedAt); err != nil {
