		status, sender_confirmed, receiver_confirmed, sender_confirmed_at, receiver_confirmed_at, initiated_at, completed_at
		FROM handoffs WHERE sample_id=$1 AND status='pending' ORDER BY initiated_at DESC LIMIT 1`, sampleID)
	var h Handoff
	if err := row.Scan(&h.HandoffID, &h.SampleID, &h.FromAssignmentID, &h.ToAssignmentID, &h.SenderID, &h.ReceiverID,
