}

// HandoffsByReceiver returns pending/active handoffs for a worker (as sender or receiver).
func (s *Store) HandoffsByParty(ctx context.Context, userID uuid.UUID) ([]*Handoff, error) {
	rows, err := s.PG.Query(ctx, `SELECT handoff_id, sample_id, from_assignment_id, to_assignment_id, sender_id, receiver_id,
		status, sender_confirmed, receiver_confirmed, sender_confirmed_at, receiver_confirmed_at, initiated_at, completed_at
		FROM handoffs WHERE (sender_id=$1 OR receiver_id=$1) AND status='pending' ORDER BY initiated_at DESC`, userID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []*Handoff
	for rows.Next() {
		var h Handoff
		if err := rows.Scan(&h.HandoffID, &h.SampleID, &h.FromAssignmentID, &h.ToAssignmentID, &h.SenderID, &h.ReceiverID,
			&h.Status, &h.SenderConfirmed, &h.ReceiverConfirmed, &h.SenderConfirmedAt, &h.ReceiverConfirmedAt, &h.InitiatedAt, &h.CompletedAt); err != nil {
			return nil, err
		}
