type Worker struct {
	UserID        uuid.UUID
	Available     bool
	CapacityUnits int
	AssignedCount int
}

func (s *Store) Worker(ctx context.Context, userID uuid.UUID) (*Worker, error) {
	var w Worker
	err := s.PG.QueryRow(ctx, "SELECT user_id, worker_available, worker_capacity_units, assignment_count FROM users WHERE user_id=$1", userID).
		Scan(&w.UserID, &w.Available, &w.CapacityUnits, &w.AssignedCount)
	return &w, err
}

func (s *Store) SetWorkerAvailability(ctx context.Context, tx pgx.Tx, userID uuid.UUID, available bool, capacity int) error {
	_, err := tx.Exec(ctx, "UPDATE users SET worker_available=$2, worker_capacity_units=$3 WHERE user_id=$1", userID, available, capacity)
	return err
