// UpdateSampleLocation records a worker's last known location for a sample.
func (s *Store) UpdateSampleLocation(ctx context.Context, tx pgx.Tx, sampleID uuid.UUID, lat, lon float64, at time.Time) error {
	_, err := tx.Exec(ctx, `UPDATE samples SET latest_lat=$2, latest_lon=$3, location_recorded_at=$4, location_stale=FALSE WHERE sample_id=$1`,
		sampleID, lat, lon, at)
	return err
}

// ============================================================================
// Journeys, stops, assignments
// ============================================================================

type Journey struct {
	JourneyID         uuid.UUID
	ParentJourneyID   *uuid.UUID
	RequestID         *uuid.UUID
	PlanVersion        int
	RouteMode         string
	Status            string
	EstimatedDelivery *time.Time
	TotalCost         float64
	SampleIDs         []uuid.UUID
	Valid             bool
	ReplanStatus      *string
	Active            bool
}

type Stop struct {
	StopID         uuid.UUID
	LocationID     uuid.UUID
	StopType       string
	Sequence       int
	EstimatedAt    time.Time
	DwellMinutes   int
	CompletedAt    *time.Time
}

type Leg struct {
	AssignmentID uuid.UUID
	Sequence     int
	Status       string
	FromLocation *uuid.UUID
	ToLocation   *uuid.UUID
