		(handoff_id, sample_id, from_assignment_id, to_assignment_id, sender_id, receiver_id, status, sender_confirmed,
		 receiver_confirmed, initiated_at)
		VALUES ($1,$2,$3,$4,$5,$6,'pending',FALSE,FALSE,$7)`,
		h.HandoffID, h.SampleID, h.FromAssignmentID, h.ToAssignmentID, h.SenderID, h.ReceiverID, h.InitiatedAt)
	return err
