	m.HandleFunc("POST /api/journeys/{journeyId}/reroute", s.dispatcherOnly(s.handleRerouteJourney))
	m.HandleFunc("POST /api/journeys/{journeyId}/cancel", s.dispatcherOnly(s.handleCancelJourney))
