	m.HandleFunc("POST /api/report-disruption", s.dispatcherOnly(s.handleReportDisruption))
	m.HandleFunc("POST /api/read-operations-state", s.dispatcherOnly(s.handleReadOperationsState))

	// Work & assignments
	m.HandleFunc("POST /api/list-role-work", s.authed(s.handleListRoleWork))
	m.HandleFunc("POST /api/accept-assignment", s.workerOnly(s.handleAcceptAssignment))
	m.HandleFunc("POST /api/decline-assignment", s.workerOnly(s.handleDeclineAssignment))
	m.HandleFunc("POST /api/collect-and-seal-sample", s.collectionProOnly(s.handleCollectAndSealSample))
	m.HandleFunc("POST /api/update-assignment-progress", s.deliveryOnly(s.handleUpdateAssignmentProgress))
