	writeData(w, http.StatusOK, map[string]string{"status": "ready"})
}

// handleAuthenticate validates credentials and returns a session token.
func (s *Server) handleAuthenticate(w http.ResponseWriter, r *http.Request) {
	var req struct {
		Username string `json:"username"`
		Password string `json:"password"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	if req.Username == "" || req.Password == "" {
		writeErr(w, http.StatusBadRequest, "invalid_request", "username and password required")
		return
	}
	user, hash, err := s.Store.UserByUsername(r.Context(), req.Username)
	if err != nil || user == nil {
		writeErr(w, http.StatusUnauthorized, "unauthorized", "invalid credentials")
		return
	}
	if !auth.CheckPassword(hash, req.Password) {
		writeErr(w, http.StatusUnauthorized, "unauthorized", "invalid credentials")
		return
	}
	if !user.Active {
		writeErr(w, http.StatusConflict, "account_inactive", "user account is not active")
		return
	}
	token := auth.NewToken()
	activeRole := ""
	if len(user.Roles) > 0 {
		activeRole = user.Roles[0]
	}
	_, err = s.Store.PG.Exec(r.Context(), `INSERT INTO sessions (session_token, user_id, active_role) VALUES ($1,$2,$3)`, token, user.UserID, activeRole)
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal", "could not create session")
		return
	}
	s.Audit.Record(r.Context(), auditEntry(principal(user, activeRole), "sign_in", "user", user.UserID.String(), true, "authenticated"))
	writeData(w, http.StatusOK, map[string]any{
		"sessionToken": token,
		"userId":       user.UserID.String(),
		"roles":        user.Roles,
		"activeRole":   activeRole,
	})
}

// handleSelectActiveRole sets the active role on the current session.
func (s *Server) handleSelectActiveRole(w http.ResponseWriter, r *http.Request) {
	pr := principalFrom(r)
	var req struct {
		Role string `json:"role"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	if !store.ValidRole(req.Role) {
		writeErr(w, http.StatusBadRequest, "invalid_role", "unknown role")
		return
	}
	allowed := false
	for _, rr := range pr.User.Roles {
		if rr == req.Role {
			allowed = true
		}
	}
	if !allowed {
		writeErr(w, http.StatusForbidden, "forbidden", "account does not hold this role")
		return
	}
	token := bearerToken(r)
	if _, err := s.Store.PG.Exec(r.Context(), "UPDATE sessions SET active_role=$2 WHERE session_token=$1", token, req.Role); err != nil {
		writeErr(w, http.StatusInternalServerError, "internal", "could not update role")
		return
	}
	pr.Role = req.Role
	s.Audit.Record(r.Context(), auditEntry(pr, "select_role", "user", pr.User.UserID.String(), true, "role="+req.Role))
	writeData(w, http.StatusOK, map[string]any{
		"activeRole": req.Role,
		"roles":      pr.User.Roles,
	})
}

// handleReadUser returns a user by id.
func (s *Server) handleReadUser(w http.ResponseWriter, r *http.Request) {
	uid, err := uuid.Parse(r.PathValue("userId"))
	if err != nil {
		writeErr(w, http.StatusBadRequest, "invalid_request", "invalid userId")
		return
	}
	u, err := s.Store.UserByID(r.Context(), uid)
	if err != nil || u == nil {
		writeErr(w, http.StatusNotFound, "not_found", "user not found")
		return
	}
	writeData(w, http.StatusOK, userResponse(u))
}

// bearerToken extracts the Bearer [REDACTED] from the Authorization header.
func bearerToken(r *http.Request) string {
	h := r.Header.Get("Authorization")
	if len(h) > 7 && h[:7] == "Bearer " {
		return h[7:]
	}
	return ""
}

func userResponse(u *store.User) map[string]any {
	certs := []map[string]any{}
	for _, c := range u.Certifications {
		m := map[string]any{"code": c.Code, "active": c.Active}
		if c.ExpiresAt != nil {
			m["expiresAt"] = c.ExpiresAt.Format(time.RFC3339Nano)
		}
		certs = append(certs, m)
	}
	resp := map[string]any{
		"userId":         u.UserID.String(),
		"username":       u.Username,
		"roles":          u.Roles,
		"qualifications": u.Qualifications,
		"certifications": certs,
		"active":         u.Active,
	}
	if u.Email != "" {
		resp["email"] = u.Email
	}
	if u.FullName != "" {
		resp["fullName"] = u.FullName
	}
	if u.Phone != "" {
		resp["phone"] = u.Phone
	}
	return resp
}

// handleCreateUser creates a user (admin).
func (s *Server) handleCreateUser(w http.ResponseWriter, r *http.Request) {
	pr := principalFrom(r)
	var req struct {
		Username        string         `json:"username"`
		InitialPassword string         `json:"initialPassword"`
		Email           string         `json:"email"`
		FullName        string         `json:"fullName"`
		Phone           string         `json:"phone"`
		Roles           []string       `json:"roles"`
		Qualifications  []string       `json:"qualifications"`
		Certifications  []map[string]any `json:"certifications"`
		Active          bool           `json:"active"`
		AssignedLocationID *string     `json:"assignedLocationId"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	if req.Username == "" || req.InitialPassword == "" {
		writeErr(w, http.StatusBadRequest, "invalid_request", "username and initialPassword required")
		return
	}
	for _, rr := range req.Roles {
		if !store.ValidRole(rr) {
			writeErr(w, http.StatusBadRequest, "invalid_role", "unknown role: "+rr)
			return
		}
	}
	hash, err := auth.HashPassword(req.InitialPassword)
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal", "could not hash password")
		return
	}
	var assigned *uuid.UUID
	if req.AssignedLocationID != nil && *req.AssignedLocationID != "" {
		id, err := uuid.Parse(*req.AssignedLocationID)
		if err == nil {
			assigned = &id
		}
	}
	u := &store.User{
		Username: req.Username, Email: req.Email, FullName: req.FullName, Phone: req.Phone,
		Roles: req.Roles, Qualifications: req.Qualifications, Active: req.Active,
		AssignedLocationID: assigned,
	}
	for _, c := range req.Certifications {
		code, _ := c["code"].(string)
		active, _ := c["active"].(bool)
		u.Certifications = append(u.Certifications, store.Certification{Code: code, Active: active})
	}
	err = inTx(r.Context(), s.Store, func(tx interface{ exec(ctx context.Context) error }) error { return nil })
	_ = err
	txErr := withTx(r.Context(), s.Store, func(tx pgTx) error {
		return s.Store.CreateUser(r.Context(), tx, u, hash)
	})
	if txErr != nil {
		if isUniqueViolation(txErr) {
			writeErr(w, http.StatusConflict, "duplicate", "username already exists")
			return
		}
		writeErr(w, http.StatusInternalServerError, "internal", "could not create user")
		return
	}
	s.Audit.Record(r.Context(), auditEntry(pr, "create_user", "user", u.UserID.String(), true, "username="+u.Username))
	writeData(w, http.StatusCreated, userResponse(u))
}

// handleUpdateUserAccess updates roles/qualifications/certs/active.
func (s *Server) handleUpdateUserAccess(w http.ResponseWriter, r *http.Request) {
	pr := principalFrom(r)
	var req struct {
		UserID          string         `json:"userId"`
		Roles           []string       `json:"roles"`
		Qualifications  []string       `json:"qualifications"`
		Certifications  []map[string]any `json:"certifications"`
		Active          bool           `json:"active"`
		AssignedLocationID *string     `json:"assignedLocationId"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	uid, err := uuid.Parse(req.UserID)
	if err != nil {
		writeErr(w, http.StatusBadRequest, "invalid_request", "invalid userId")
		return
	}
	for _, rr := range req.Roles {
		if !store.ValidRole(rr) {
			writeErr(w, http.StatusBadRequest, "invalid_role", "unknown role: "+rr)
			return
		}
	}
	var assigned *uuid.UUID
	if req.AssignedLocationID != nil && *req.AssignedLocationID != "" {
		id, err := uuid.Parse(*req.AssignedLocationID)
		if err == nil {
			assigned = &id
		}
	}
	err = withTx(r.Context(), s.Store, func(tx pgTx) error {
		if _, err := tx.Exec(r.Context(), `UPDATE users SET active=$2, assigned_location_id=$3 WHERE user_id=$1`, uid, req.Active, assigned); err != nil {
			return err
		}
		if _, err := tx.Exec(r.Context(), "DELETE FROM user_roles WHERE user_id=$1", uid); err != nil {
			return err
		}
		for _, rr := range req.Roles {
			if _, err := tx.Exec(r.Context(), "INSERT INTO user_roles (user_id, role) VALUES ($1,$2)", uid, rr); err != nil {
				return err
			}
		}
		if _, err := tx.Exec(r.Context(), "DELETE FROM qualifications WHERE user_id=$1", uid); err != nil {
			return err
		}
		for _, q := range req.Qualifications {
			if _, err := tx.Exec(r.Context(), "INSERT INTO qualifications (user_id, code) VALUES ($1,$2)", uid, q); err != nil {
				return err
			}
		}
		if _, err := tx.Exec(r.Context(), "DELETE FROM certifications WHERE user_id=$1", uid); err != nil {
			return err
		}
		for _, c := range req.Certifications {
			code, _ := c["code"].(string)
			active, _ := c["active"].(bool)
			cid := uuid.New()
			if _, err := tx.Exec(r.Context(), "INSERT INTO certifications (cert_id, user_id, code, active) VALUES ($1,$2,$3,$4)", cid, uid, code, active); err != nil {
				return err
			}
		}
		return nil
	})
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal", "could not update user")
		return
	}
	u, err := s.Store.UserByID(r.Context(), uid)
	if err != nil || u == nil {
		writeErr(w, http.StatusNotFound, "not_found", "user not found")
		return
	}
	s.Audit.Record(r.Context(), auditEntry(pr, "update_user_access", "user", uid.String(), true, "roles updated"))
	writeData(w, http.StatusCreated, userResponse(u))
}

// handleSetWorkerAvailability (admin/dispatcher) toggles a worker's availability.
func (s *Server) handleSetWorkerAvailability(w http.ResponseWriter, r *http.Request) {
	pr := principalFrom(r)
	var req struct {
		WorkerID      string `json:"workerId"`
		Available     bool   `json:"available"`
		CapacityUnits int    `json:"capacityUnits"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	uid, err := uuid.Parse(req.WorkerID)
	if err != nil {
		writeErr(w, http.StatusBadRequest, "invalid_request", "invalid workerId")
		return
	}
	if req.CapacityUnits <= 0 {
		req.CapacityUnits = 4
	}
	err = withTx(r.Context(), s.Store, func(tx pgTx) error {
		return s.Store.SetWorkerAvailability(r.Context(), tx, uid, req.Available, req.CapacityUnits)
	})
	if err != nil {
		writeErr(w, http.StatusNotFound, "not_found", "worker not found")
		return
	}
	s.Audit.Record(r.Context(), auditEntry(pr, "set_worker_availability", "user", uid.String(), true, ""))
	writeData(w, http.StatusOK, map[string]any{
		"workerId":      uid.String(),
		"available":     req.Available,
		"capacityUnits": req.CapacityUnits,
	})
}

// helpers ---------------------------------------------------------------------

// pgTx is the minimal transaction interface the handlers use.
type pgTx interface {
	Exec(ctx context.Context, sql string, args ...any) (commandTag, error)
}

// commandTag mirrors pgconn.CommandTag string behaviour.
type commandTag interface{}

// withTx runs fn inside a pgx transaction.
func withTx(ctx context.Context, s *store.Store, fn func(pgTx) error) error {
	tx, err := s.PG.BeginTx(ctx, pgxBEGIN)
	if err != nil {
		return err
	}
	defer tx.Rollback(ctx)
	if err := fn(&txWrapper{tx: tx}); err != nil {
		return err
	}
	return tx.Commit(ctx)
}

type txWrapper struct {
	txx
}

type txx interface {
	Exec(ctx context.Context, sql string, args ...any) (commandTag, error)
}

func (t *txWrapper) Exec(ctx context.Context, sql string, args ...any) (commandTag, error) {
	return t.tx.Exec(ctx, sql, args...)
}

func isUniqueViolation(err error) bool {
	if err == nil {
		return false
	}
	return errors.Is(err, errUnique) || containsMsg(err.Error(), "duplicate key")
}

func containsMsg(s, sub string) bool {
	return len(s) >= len(sub) && (s == sub || indexOf(s, sub) >= 0)
}
func indexOf(s, sub string) int {
	for i := 0; i+len(sub) <= len(s); i++ {
		if s[i:i+len(sub)] == sub {
			return i
		}
	}
	return -1
}

var errUnique = errors.New("unique violation")

// errSQLDuplicate signals a Postgres unique_violation (SQLSTATE 23505).
type errSQLDuplicate struct{}

func (errSQLDuplicate) Error() string { return "duplicate key" }

// Unused but keeps sql import referenced for scan helpers if needed.
var _ = sql.ErrNoRows

// pgxBEGIN is a sentinel for pgx.BeginTx options; real option set in main wiring.
var pgxBEGIN = pgxBeginOptions{}

