func (s *Store) JourneyByID(ctx context.Context, id uuid.UUID) (*Journey, error) {
	row := s.PG.QueryRow(ctx, `SELECT journey_id, parent_journey_id, request_id, plan_version, route_mode, status,
		estimated_delivery_at, total_cost_units, sample_ids, valid, replan_status, active
		FROM journeys WHERE journey_id=$1`, id)
	var j Journey
	var est *time.Time
	var replan *string
	if err := row.Scan(&j.JourneyID, &j.ParentJourneyID, &j.RequestID, &j.PlanVersion, &j.RouteMode, &j.Status,
		&est, &j.TotalCost, &j.SampleIDs, &j.Valid, &replan, &j.Active); err != nil {
		return nil, err
	}
	j.EstimatedDelivery = est
	j.ReplanStatus = replan
	return &j, nil
}

func (s *Store) JourneysBySample(ctx context.Context, sampleID uuid.UUID) ([]*Journey, error) {
