func (s *Store) CreateStop(ctx context.Context, tx pgx.Tx, journeyID uuid.UUID, st *Stop) error {
	if st.StopID == uuid.Nil {
		st.StopID = uuid.New()
	}
	_, err := tx.Exec(ctx, `INSERT INTO stops (stop_id, journey_id, location_id, stop_type, sequence, estimated_at, dwell_minutes)
		VALUES ($1,$2,$3,$4,$5,$6,$7)`,
		st.StopID, journeyID, st.LocationID, st.StopType, st.Sequence, st.EstimatedAt, st.DwellMinutes)
	return err
}

func (s *Store) StopsByJourney(ctx context.Context, journeyID uuid.UUID) ([]Stop, error) {
	rows, err := s.PG.Query(ctx, `SELECT stop_id, location_id, stop_type, sequence, estimated_at, dwell_minutes, completed_at
		FROM stops WHERE journey_id=$1 ORDER BY sequence`, journeyID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []Stop
	for rows.Next() {
		var st Stop
		if err := rows.Scan(&st.StopID, &st.LocationID, &st.StopType, &st.Sequence, &st.EstimatedAt, &st.DwellMinutes, &st.CompletedAt); err != nil {
			return nil, err
		}
		out = append(out, st)
	}
	return out, nil
}

