import (
	"context"
	"encoding/json"
	"sync"
	"time"

	"github.com/google/uuid"
	"github.com/labsample/app/internal/store"
)

// Region describes one active collection point's coverage region.
type Region struct {
	LocationID  uuid.UUID `json:"locationId"`
	Name        string    `json:"name"`
	Latitude    float64   `json:"latitude"`
	Longitude   float64   `json:"longitude"`
	CoverageKm  float64   `json:"coverageKm"`
}

// Snapshot is a published, complete serviceability-calculation version.
type Snapshot struct {
	Version                    int       `json:"version"`
	Status                     string    `json:"status"`
	ComputedAt                 time.Time `json:"computedAt"`
	NetworkRevision            int       `json:"networkRevision"`
	Regions                    []Region  `json:"regions"`
	ActiveCollectionPointCount int       `json:"activeCollectionPointCount"`
}

// SnapshotManager keeps one complete serviceability version served at a time.
type SnapshotManager struct {
	store *store.Store
	mu    sync.Mutex
}

func NewSnapshotManager(s *store.Store) *SnapshotManager {
	return &SnapshotManager{store: s}
}

// Get returns the current complete (ready) snapshot.
func (m *SnapshotManager) Get(ctx context.Context) (*Snapshot, error) {
	m.mu.Lock()
	defer m.mu.Unlock()
	row := m.store.PG.QueryRow(ctx, `SELECT version, status, computed_at, network_revision, regions, active_collection_point_count
		FROM serviceability_snapshots WHERE status='ready' ORDER BY version DESC LIMIT 1`)
	var s Snapshot
	var computed *time.Time
	var regions []byte
	if err := row.Scan(&s.Version, &s.Status, &computed, &s.NetworkRevision, &regions, &s.ActiveCollectionPointCount); err != nil {
		// No snapshot yet — compute an initial one.
		return m.Recompute(ctx, 1)
	}
	if computed != nil {
		s.ComputedAt = *computed
	}
	if len(regions) > 0 {
		_ = json.Unmarshal(regions, &s.Regions)
	}
	return &s, nil
}

// Recompute computes a new complete version while the previous ready version
// keeps being served. The new version becomes ready only when fully computed.
func (m *SnapshotManager) Recompute(ctx context.Context, networkRevision int) (*Snapshot, error) {
	m.mu.Lock()
	defer m.mu.Unlock()
	// Find the next version number.
	var maxVer int
	_ = m.store.PG.QueryRow(ctx, "SELECT COALESCE(max(version),0) FROM serviceability_snapshots").Scan(&maxVer)
	nextVer := maxVer + 1
	// Insert a "computing" row.
	_, err := m.store.PG.Exec(ctx, `INSERT INTO serviceability_snapshots (version, status, network_revision, regions, active_collection_point_count)
		VALUES ($1,'computing',$2,'[]',0)`, nextVer, networkRevision)
	if err != nil {
		// Possibly already computing this version; ignore.
	}
	// Build regions from active collection points.
	locs, err := m.store.AllLocations(ctx)
	if err != nil {
		return nil, err
	}
	var regions []Region
	for _, l := range locs {
		if l.Active && l.Functions.CollectionPoint {
			regions = append(regions, Region{
				LocationID: l.LocationID, Name: l.Name,
				Latitude: l.Lat, Longitude: l.Lon, CoverageKm: l.CoverageKm,
			})
		}
	}
	regionsJSON, _ := json.Marshal(regions)
	now := time.Now().UTC()
	// Finalize: mark ready.
	_, err = m.store.PG.Exec(ctx, `UPDATE serviceability_snapshots SET status='ready', computed_at=$3, regions=$4, active_collection_point_count=$5 WHERE version=$1`,
		nextVer, nil, now, regionsJSON, len(regions))
	if err != nil {
		return nil, err
	}
	return &Snapshot{
		Version: nextVer, Status: "ready", ComputedAt: now,
		NetworkRevision: networkRevision, Regions: regions,
		ActiveCollectionPointCount: len(regions),
	}, nil
}package geo

import "math"

// HaversineKm returns the great-circle distance between two coordinates in km.
func HaversineKm(lat1, lon1, lat2, lon2 float64) float64 {
	const r = 6371.0 // Earth radius in km
	la1 := lat1 * math.Pi / 180
	la2 := lat2 * math.Pi / 180
	dlat := (lat2 - lat1) * math.Pi / 180
	dlon := (lon2 - lon1) * math.Pi / 180
	a := math.Sin(dlat/2)*math.Sin(dlat/2) +
		math.Cos(la1)*math.Cos(la2)*math.Sin(dlon/2)*math.Sin(dlon/2)
	c := 2 * math.Atan2(math.Sqrt(a), math.Sqrt(1-a))
	return r * c
}[?2004h

