	_ = decodeBody(w, r, &req)
	snap, err := s.Snap.Get(r.Context())
	if err != nil || snap == nil {
		snap, err = s.Snap.Recompute(r.Context(), 1)
		if err != nil {
			writeErr(w, http.StatusInternalServerError, "internal", "could not compute snapshot")
			return
		}
	}
	regions := []map[string]any{}
	for _, reg := range snap.Regions {
		regions = append(regions, map[string]any{
			"locationId": reg.LocationID.String(),
			"name":       reg.Name,
