}

// handleIngestPresealedSample registers an already-sealed sample (clinic/node origin).
func (s *Server) handleIngestPresealedSample(w http.ResponseWriter, r *http.Request) {
	s.createRequest(w, r, true)
}

func (s *Server) createRequest(w http.ResponseWriter, r *http.Request, alreadySealed bool) {
	pr := principalFrom(r)
	var req struct {
		RequesterID   string             `json:"requesterId"`
		Origin        map[string]float64 `json:"origin"`
		OriginType    string             `json:"originType"`
		OriginNodeID  string             `json:"originNodeId"`
		RequestedAt   string             `json:"requestedAt"`
		DeliveryDeadline string          `json:"deliveryDeadline"`
		EarliestCollectionAt string      `json:"earliestCollectionAt"`
		LatestCollectionAt   string      `json:"latestCollectionAt"`
		SampleTypeID  string             `json:"sampleTypeId"`
		ContainerType string             `json:"containerType"`
		TemperatureMinC *float64         `json:"temperatureMinC"`
		TemperatureMaxC *float64         `json:"temperatureMaxC"`
		IncompatibleSampleTypes []string `json:"incompatibleSampleTypes"`
		IdempotencyKey string             `json:"idempotencyKey"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	lat, lon := req.Origin["latitude"], req.Origin["longitude"]
	stID, err := uuid.Parse(req.SampleTypeID)
	if err != nil {
		writeErr(w, http.StatusBadRequest, "invalid_request", "invalid sampleTypeId")
		return
	}
	requestedAt, ok := parseTime(req.RequestedAt)
	if !ok {
		requestedAt = time.Now().UTC()
	}
	deadline, ok := parseTime(req.DeliveryDeadline)
	if !ok {
		writeErr(w, http.StatusBadRequest, "invalid_request", "invalid deliveryDeadline")
		return
	}
	earliest, _ := parseTime(req.EarliestCollectionAt)
	if earliest.IsZero() {
		earliest = requestedAt
	}
	latest, _ := parseTime(req.LatestCollectionAt)
	if latest.IsZero() {
		latest = deadline
	}
	incompat, ok := parseIDs(req.IncompatibleSampleTypes)
	if !ok {
		writeErr(w, http.StatusBadRequest, "invalid_request", "invalid incompatibleSampleTypes")
		return
	}
	if alreadySealed && req.OriginType == "home" {
		writeErr(w, http.StatusBadRequest, "invalid_request", "pre-sealed sample origin must be clinic or node")
		return
	}
	st, err := s.Store.SampleTypeByID(r.Context(), stID)
	if err != nil || st == nil {
		writeErr(w, http.StatusNotFound, "not_found", "sample type not found")
		return
	}
	var originNode *uuid.UUID
	if req.OriginNodeID != "" {
		id, err := uuid.Parse(req.OriginNodeID)
		if err == nil {
			originNode = &id
		}
	}
	container := req.ContainerType
	if container == "" {
		container = st.ContainerType
	}

	// Resolve requester: use provided id, else current user.
	var requesterID uuid.UUID
	if req.RequesterID != "" {
		requesterID, err = uuid.Parse(req.RequesterID)
		if err != nil {
			requesterID = pr.User.UserID
		}
	} else {
		requesterID = pr.User.UserID
	}

	// Serviceability dry run against network structure.
	result, err := s.Engine.PlanRoute(r.Context(), lat, lon, originNode, stID, st.RequiresCooledRoute, earliest, deadline)
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal", "serviceability failed")
		return
	}
	serviceable := result.Serviceable
	reason := result.Reason

	var requestID, sampleID uuid.UUID
	var journey *store.Journey
	var assignmentIDs []string
	var targetLabID *uuid.UUID
	err = withTx(r.Context(), s.Store, func(tx pgx.Tx) error {
		sampleID = uuid.New()
		requestID = uuid.New()
		if serviceable {
			targetLabID = &result.TargetLabID
		}
		sm := &store.Sample{
			SampleID: sampleID, RequestID: requestID, RequesterID: requesterID, SampleTypeID: stID,
			ContainerType: container, TemperatureMinC: req.TemperatureMinC, TemperatureMaxC: req.TemperatureMaxC,
			Incompatible: incompat, OriginType: req.OriginType, OriginLat: lat, OriginLon: lon, OriginNodeID: originNode,
			RequestedAt: requestedAt, DeliveryDeadline: deadline, EarliestColl: &earliest, LatestColl: &latest,
			Status: "requested", Sealed: alreadySealed, TargetLabID: targetLabID,
		}
		if alreadySealed {
			sm.SealedAt = &requestedAt
			sm.CurrentHolderID = &requesterID
		}
		if err := s.Store.CreateSample(r.Context(), tx, sm); err != nil {
			return err
		}
		if err := s.Store.CreateRequest(r.Context(), tx, requestID, sampleID, requesterID, lat, lon, req.OriginType, originNode,
			requestedAt, deadline, &earliest, &latest, stID, container, req.TemperatureMinC, req.TemperatureMaxC, incompat,
			serviceable, reason, alreadySealed); err != nil {
			return err
		}
		if serviceable {
			// Create a journey with stops/assignments along the planned route.
			j := &store.Journey{
				PlanVersion: 1, RouteMode: routeModeFor(result.RouteLocations), Status: "planned",
				EstimatedDelivery: &result.EstimatedArrival, TotalCost: result.TotalCost,
				SampleIDs: []uuid.UUID{sampleID}, Valid: true,
			}
			if err := s.Store.CreateJourney(r.Context(), tx, j); err != nil {
				return err
			}
			journey = j
			// Build stops along route locations.
			arrival := earliest
			for i, locID := range result.RouteLocations {
				stopType := "pickup"
				if i == len(result.RouteLocations)-1 {
					stopType = "delivery"
				} else if i > 0 {
					stopType = "handoff"
				}
				stp := &store.Stop{LocationID: locID, StopType: stopType, Sequence: i + 1, EstimatedAt: arrival}
				if err := s.Store.CreateStop(r.Context(), tx, j.JourneyID, stp); err != nil {
					return err
				}
				if i < len(result.RouteLocations)-1 {
					arrival = arrival.Add(time.Duration(estimateLegMinutes(result.RouteLocations, i)) * time.Minute)
				}
			}
			// Create assignments: collection at first node, transport legs, lab receipt.
			assignmentIDs, err = s.buildAssignments(r.Context(), tx, j.JourneyID, sampleID, result.RouteLocations, st, alreadySealed, originNode)
			if err != nil {
				return err
			}
			_, err = tx.Exec(r.Context(), "UPDATE samples SET active_journey_id=$2 WHERE sample_id=$1", sampleID, j.JourneyID)
			if err != nil {
				return err
			}
		}
		return nil
	})
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal", "could not create request")
		return
	}
	servStr := "unserviceable"
	if serviceable {
		servStr = "serviceable"
	}
	originType := req.OriginType
	if originType == "" {
		originType = "home"
	}
	s.Audit.Record(r.Context(), auditEntry(pr, "create_collection_request", "request", requestID.String(), true, servStr))
	resp := map[string]any{
		"requestId":             requestID.String(),
		"sampleId":              sampleID.String(),
		"serviceability":        servStr,
		"serviceabilityReason":  reason,
		"activeAssignmentIds":   assignmentIDs,
		"earliestCollectionAt":  formatTime(earliest),
		"latestCollectionAt":    formatTime(latest),
		"alreadySealed":         alreadySealed,
		"originType":            originType,
	}
	if journey != nil {
		resp["journeyId"] = journey.JourneyID.String()
	} else {
		resp["journeyId"] = ""
	}
	if targetLabID != nil {
		resp["targetLaboratoryId"] = targetLabID.String()
	} else {
		resp["targetLaboratoryId"] = ""
	}
	writeCreated(w, resp)
}

// routeModeFor infers direct/multi_stop/batched from the route length.
func routeModeFor(route []uuid.UUID) string {
	switch {
	case len(route) <= 2:
		return "direct"
	case len(route) <= 4:
		return "multi_stop"
	default:
		return "batched"
	}
}

// estimateLegMinutes is a coarse per-leg estimate based on the engine's totals.
func estimateLegMinutes(route []uuid.UUID, i int) int {
	return 30
}

// buildAssignments creates collection/transport/node/lab assignments for a route
// and tries to offer them to eligible workers one at a time.
func (s *Server) buildAssignments(ctx interface{ Done() <-chan struct{} }, tx pgx.Tx, journeyID, sampleID uuid.UUID, route []uuid.UUID, st *store.SampleType, alreadySealed bool, originNode *uuid.UUID) ([]string, error) {
	var ids []string
	if len(route) == 0 {
		return ids, nil
	}
	seq := 0
	// Collection assignment (skipped when sample already sealed at registration).
	if !alreadySealed {
		seq++
		col := &store.Assignment{
			JourneyID: journeyID, SampleID: sampleID, Kind: "collection", Sequence: seq,
			Status: "offered", ToLocation: &route[0], Cooled: st.RequiresCooledRoute,
		}
		if err := s.Store.CreateAssignment(ctx, tx, col); err != nil {
			return nil, err
		}
		ids = append(ids, col.AssignmentID.String())
		s.offerToEligibleWorker(ctx, tx, col, "collection", st)
	}
	// Transport legs between consecutive route locations.
	for i := 0; i < len(route)-1; i++ {
		seq++
		from := route[i]
		to := route[i+1]
		leg := &store.Assignment{
			JourneyID: journeyID, SampleID: sampleID, Kind: "transport", Sequence: seq,
			Status: "offered", FromLocation: &from, ToLocation: &to, Cooled: st.RequiresCooledRoute,
		}
		if err := s.Store.CreateAssignment(ctx, tx, leg); err != nil {
			return nil, err
		}
		ids = append(ids, leg.AssignmentID.String())
		s.offerToEligibleWorker(ctx, tx, leg, "transport", st)
	}
	// Laboratory receipt assignment at the final lab.
	if len(route) > 0 {
		seq++
		lab := route[len(route)-1]
		labAssign := &store.Assignment{
			JourneyID: journeyID, SampleID: sampleID, Kind: "laboratory", Sequence: seq,
			Status: "offered", LaboratoryID: &lab, Cooled: st.RequiresCooledRoute,
		}
		if err := s.Store.CreateAssignment(ctx, tx, labAssign); err != nil {
			return nil, err
		}
		ids = append(ids, labAssign.AssignmentID.String())
		s.offerToEligibleWorker(ctx, tx, labAssign, "laboratory", st)
	}
	return ids, nil
}

// offerToEligibleWorker finds the most appropriate eligible+available worker
// for the assignment and offers it to them. None available -> flagged via audit.
func (s *Server) offerToEligibleWorker(ctx interface{ Done() <-chan struct{} }, tx pgx.Tx, a *store.Assignment, kind string, st *store.SampleType) {
	workers, _ := s.Store.AllWorkers(ctx)
	best := s.pickWorker(ctx, workers, a, kind, st)
	if best == uuid.Nil {
		// No qualified worker available: flag an exception reason distinct from deadline.
		reason := "no_qualified_worker"
		_, _ = tx.Exec(ctx, "UPDATE samples SET exception_kind=$2 WHERE sample_id=$1", a.SampleID, reason)
		return
	}
	_ = s.Store.OfferAssignment(ctx, tx, a.AssignmentID, best)
}

// pickWorker chooses the eligible worker with lowest current assignment count.
func (s *Server) pickWorker(ctx interface{ Done() <-chan struct{} }, workers []uuid.UUID, a *store.Assignment, kind string, st *store.SampleType) uuid.UUID {
	var best uuid.UUID
	var bestCount = 1 << 30
	for _, wid := range workers {
		w, err := s.Store.Worker(ctx, wid)
		if err != nil || w == nil || !w.Available {
			continue
		}
		// Node/lab assignments require the worker to be assigned to that node/lab.
		if kind == "node" || kind == "laboratory" {
			u, _ := s.Store.UserByID(ctx, wid)
			if u == nil || u.AssignedLocationID == nil {
				continue
			}
			target := a.NodeID
			if kind == "laboratory" {
				target = a.LaboratoryID
			}
			if target == nil || *u.AssignedLocationID != *target {
				continue
			}
		}
		// Collection requires matching qualification.
		if kind == "collection" && st.QualifiedCollectorRequired {
			u, _ := s.Store.UserByID(ctx, wid)
			if u == nil || !hasQualification(u.Qualifications, st.RequiredQualification) {
				continue
			}
		}
		if w.AssignedCount < bestCount {
			bestCount = w.AssignedCount
			best = wid
		}
	}
	return best
}

func hasQualification(qs []string, q string) bool {
	for _, x := range qs {
		if x == q {
			return true
		}
	}
	return false
