	var requesterID uuid.UUID
	if req.RequesterID != "" {
		requesterID, err = uuid.Parse(req.RequesterID)
		if err != nil {
			requesterID = pr.User.UserID
		}
	} else {
		requesterID = pr.User.UserID
	}

