	var journey *store.Journey
	var assignmentIDs []string
	var targetLabID *uuid.UUID
	err = withTx(r.Context(), s.Store, func(tx pgx.Tx) error {
		sampleID = uuid.New()
		requestID = uuid.New()
		if serviceable {
			targetLabID = &result.TargetLabID
		}
		sm := &store.Sample{
			SampleID: sampleID, RequestID: requestID, RequesterID: requesterID, SampleTypeID: stID,
			ContainerType: container, TemperatureMinC: req.TemperatureMinC, TemperatureMaxC: req.TemperatureMaxC,
			Incompatible: incompat, OriginType: req.OriginType, OriginLat: lat, OriginLon: lon, OriginNodeID: originNode,
			RequestedAt: requestedAt, DeliveryDeadline: deadline, EarliestColl: &earliest, LatestColl: &latest,
			Status: "requested", Sealed: alreadySealed, TargetLabID: targetLabID,
		}
		if alreadySealed {
			sm.SealedAt = &requestedAt
			sm.CurrentHolderID = &requesterID
		}
		if err := s.Store.CreateSample(r.Context(), tx, sm); err != nil {
			return err
		}
		if err := s.Store.CreateRequest(r.Context(), tx, requestID, sampleID, requesterID, lat, lon, req.OriginType, originNode,
			requestedAt, deadline, &earliest, &latest, stID, container, req.TemperatureMinC, req.TemperatureMaxC, incompat,
			serviceable, reason, alreadySealed); err != nil {
			return err
		}
		if serviceable {
			// Create a journey with stops/assignments along the planned route.
			j := &store.Journey{
				PlanVersion: 1, RouteMode: routeModeFor(result.RouteLocations), Status: "planned",
				EstimatedDelivery: &result.EstimatedArrival, TotalCost: result.TotalCost,
				SampleIDs: []uuid.UUID{sampleID}, Valid: true,
			}
			if err := s.Store.CreateJourney(r.Context(), tx, j); err != nil {
				return err
			}
			journey = j
			// Build stops along route locations.
			arrival := earliest
			for i, locID := range result.RouteLocations {
				stopType := "pickup"
				if i == len(result.RouteLocations)-1 {
					stopType = "delivery"
				} else if i > 0 {
					stopType = "handoff"
				}
				stp := &store.Stop{LocationID: locID, StopType: stopType, Sequence: i + 1, EstimatedAt: arrival}
				if err := s.Store.CreateStop(r.Context(), tx, j.JourneyID, stp); err != nil {
					return err
				}
				if i < len(result.RouteLocations)-1 {
