			if err != nil {
				return err
			}
			_, err = tx.Exec(r.Context(), "UPDATE samples SET active_journey_id=$2 WHERE sample_id=$1", sampleID, j.JourneyID)
			if err != nil {
				return err
			}
		}
		return nil
	})
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal", "could not create request")
		return
	}
	servStr := "unserviceable"
	if serviceable {
		servStr = "serviceable"
	}
	originType := req.OriginType
	if originType == "" {
		originType = "home"
	}
	s.Audit.Record(r.Context(), auditEntry(pr, "create_collection_request", "request", requestID.String(), true, servStr))
	resp := map[string]any{
		"requestId":             requestID.String(),
		"sampleId":              sampleID.String(),
		"serviceability":        servStr,
		"serviceabilityReason":  reason,
		"activeAssignmentIds":   assignmentIDs,
		"earliestCollectionAt":  formatTime(earliest),
		"latestCollectionAt":    formatTime(latest),
		"alreadySealed":         alreadySealed,
		"originType":            originType,
	}
	if journey != nil {
		resp["journeyId"] = journey.JourneyID.String()
	} else {
		resp["journeyId"] = ""
	}
	if targetLabID != nil {
		resp["targetLaboratoryId"] = targetLabID.String()
	} else {
		resp["targetLaboratoryId"] = ""
	}
	writeCreated(w, resp)
}

