			&sm.Incompatible, &sm.OriginType, &sm.OriginLat, &sm.OriginLon, &sm.OriginNodeID, &sm.RequestedAt, &sm.DeliveryDeadline,
			&earliest, &latest, &sm.Status, &sm.Sealed, &sealedAt, &sm.CurrentHolderID, &sm.ActiveJourneyID,
			&sm.TargetLabID, &sm.ReceivedLabID, &sm.LatestLat, &sm.LatestLon, &locAt, &sm.LocStale,
			&sm.ExceptionKind, &sm.ExceptionReason); err != nil {
			return nil, err
		}
		sm.EarliestColl = earliest
		sm.LatestColl = latest
		sm.SealedAt = sealedAt
		sm.LocRecordedAt = locAt
		out = append(out, &sm)
	}
	return out, nil
}

