// ConfirmHandoffSide marks one side confirmed and finalizes the handoff when both confirm.
func (s *Store) ConfirmHandoffSide(ctx context.Context, tx pgx.Tx, id uuid.UUID, side string, at time.Time) (*Handoff, error) {
	if side == "sender" {
		_, err := tx.Exec(ctx, "UPDATE handoffs SET sender_confirmed=TRUE, sender_confirmed_at=$2 WHERE handoff_id=$1", id, at)
		if err != nil {
			return nil, err
		}
	} else {
		_, err := tx.Exec(ctx, "UPDATE handoffs SET receiver_confirmed=TRUE, receiver_confirmed_at=$2 WHERE handoff_id=$1", id, at)
		if err != nil {
			return nil, err
		}
	}
	// If both confirmed, finalize custody.
	h, err := s.HandoffByID(ctx, id)
	if err != nil {
		return nil, err
	}
	if h.SenderConfirmed && h.ReceiverConfirmed && h.Status == "pending" {
		_, err := tx.Exec(ctx, "UPDATE handoffs SET status='confirmed', completed_at=$2 WHERE handoff_id=$1", id, at)
		if err != nil {
			return nil, err
		}
		_, err = tx.Exec(ctx, "UPDATE samples SET current_holder_id=$2 WHERE sample_id=$1", h.SampleID, h.ReceiverID)
		if err != nil {
			return nil, err
		}
		_, err = tx.Exec(ctx, "UPDATE assignments SET status='completed' WHERE assignment_id=$1", h.FromAssignmentID)
		if err != nil {
			return nil, err
		}
		h.Status = "confirmed"
		h.CompletedAt = &at
	}
	return h, nil
}

