func (s *Store) CheckpointsBySample(ctx context.Context, sampleID uuid.UUID) ([]Checkpoint, error) {
	rows, err := s.PG.Query(ctx, `SELECT checkpoint_id, assignment_id, location_id, container_type, observed_temperature_c, compliant, recorded_at
		FROM checkpoints WHERE sample_id=$1 ORDER BY recorded_at`, sampleID)
