		if err := rows.Scan(&c.CheckpointID, &c.AssignmentID, &c.LocationID, &c.ContainerType, &c.ObservedTemp, &c.Compliant, &c.RecordedAt); err != nil {
			return nil, err
		}
		out = append(out, c)
