func (s *Store) AssignmentsByWorker(ctx context.Context, workerID uuid.UUID) ([]*Assignment, error) {
	rows, err := s.PG.Query(ctx, `SELECT assignment_id, journey_id, sample_id, kind, sequence, status, from_location_id,
		to_location_id, worker_id, offered_worker_id, node_id, laboratory_id, cooled FROM assignments WHERE worker_id=$1 OR offered_worker_id=$1 ORDER BY sequence`, workerID)
	if err != nil {
