	for rows.Next() {
		var a Assignment
		if err := rows.Scan(&a.AssignmentID, &a.JourneyID, &a.SampleID, &a.Kind, &a.Sequence, &a.Status, &a.FromLocation,
			&a.ToLocation, &a.WorkerID, &a.OfferedWorkerID, &a.NodeID, &a.LaboratoryID, &a.Cooled); err != nil {
			return nil, err
		}
		out = append(out, &a)
	}
	return out, nil
}

func (s *Store) AssignmentBySampleKind(ctx context.Context, sampleID uuid.UUID, kind string) (*Assignment, error) {
	row := s.PG.QueryRow(ctx, `SELECT assignment_id, journey_id, sample_id, kind, sequence, status, from_location_id,
		to_location_id, worker_id, offered_worker_id, node_id, laboratory_id, cooled FROM assignments WHERE sample_id=$1 AND kind=$2 ORDER BY sequence DESC LIMIT 1`, sampleID, kind)
	var a Assignment
	if err := row.Scan(&a.AssignmentID, &a.JourneyID, &a.SampleID, &a.Kind, &a.Sequence, &a.Status, &a.FromLocation,
		&a.ToLocation, &a.WorkerID, &a.OfferedWorkerID, &a.NodeID, &a.LaboratoryID, &a.Cooled); err != nil {
		return nil, err
	}
	return &a, nil
}

func (s *Store) UpdateAssignmentStatus(ctx context.Context, tx pgx.Tx, id uuid.UUID, status string, workerID *uuid.UUID) error {
	if workerID != nil {
		_, err := tx.Exec(ctx, "UPDATE assignments SET status=$2, worker_id=$3 WHERE assignment_id=$1", id, status, *workerID)
		return err
	}
	_, err := tx.Exec(ctx, "UPDATE assignments SET status=$2 WHERE assignment_id=$1", id, status)
	return err
}

// OfferAssignment records an offer to a worker.
func (s *Store) OfferAssignment(ctx context.Context, tx pgx.Tx, id uuid.UUID, workerID uuid.UUID) error {
	_, err := tx.Exec(ctx, "UPDATE assignments SET offered_worker_id=$2, status='offered' WHERE assignment_id=$1", id, workerID)
	return err
}

// ReofferAssignment moves an offer to the next worker.
func (s *Store) ReofferAssignment(ctx context.Context, tx pgx.Tx, id uuid.UUID, workerID uuid.UUID) error {
	_, err := tx.Exec(ctx, "UPDATE assignments SET offered_worker_id=$2, status='offered' WHERE assignment_id=$1", id, workerID)
	return err
}

// ============================================================================
// Handoffs & checkpoints
// ============================================================================

type Handoff struct {
	HandoffID         uuid.UUID
	SampleID          uuid.UUID
	FromAssignmentID  uuid.UUID
	ToAssignmentID    uuid.UUID
	SenderID          uuid.UUID
	ReceiverID        uuid.UUID
	Status            string
	SenderConfirmed   bool
	ReceiverConfirmed bool
	SenderConfirmedAt *time.Time
	ReceiverConfirmedAt *time.Time
	InitiatedAt       time.Time
	CompletedAt       *time.Time
}

func (s *Store) CreateHandoff(ctx context.Context, tx pgx.Tx, h *Handoff) error {
	if h.HandoffID == uuid.Nil {
		h.HandoffID = uuid.New()
	}
	_, err := tx.Exec(ctx, `INSERT INTO handoffs
		(handoff_id, sample_id, from_assignment_id, to_assignment_id, sender_id, receiver_id, status, sender_confirmed,
		 receiver_confirmed, initiated_at)
		VALUES ($1,$2,$3,$4,$5,$6,'pending',FALSE,FALSE,$7)`,
		h.HandoffID, h.SampleID, h.FromAssignmentID, h.ToAssignmentID, h.SenderID, h.ReceiverID, h.InitiatedAt)
	return err
}

func (s *Store) HandoffByID(ctx context.Context, id uuid.UUID) (*Handoff, error) {
	row := s.PG.QueryRow(ctx, `SELECT handoff_id, sample_id, from_assignment_id, to_assignment_id, sender_id, receiver_id,
		status, sender_confirmed, receiver_confirmed, sender_confirmed_at, receiver_confirmed_at, initiated_at, completed_at
		FROM handoffs WHERE handoff_id=$1`, id)
	var h Handoff
	if err := row.Scan(&h.HandoffID, &h.SampleID, &h.FromAssignmentID, &h.ToAssignmentID, &h.SenderID, &h.ReceiverID,
		&h.Status, &h.SenderConfirmed, &h.ReceiverConfirmed, &h.SenderConfirmedAt, &h.ReceiverConfirmedAt, &h.InitiatedAt, &h.CompletedAt); err != nil {
		return nil, err
	}
	return &h, nil
}

func (s *Store) PendingHandoffForSample(ctx context.Context, sampleID uuid.UUID) (*Handoff, error) {
	row := s.PG.QueryRow(ctx, `SELECT handoff_id, sample_id, from_assignment_id, to_assignment_id, sender_id, receiver_id,
		status, sender_confirmed, receiver_confirmed, sender_confirmed_at, receiver_confirmed_at, initiated_at, completed_at
		FROM handoffs WHERE sample_id=$1 AND status='pending' ORDER BY initiated_at DESC LIMIT 1`, sampleID)
	var h Handoff
	if err := row.Scan(&h.HandoffID, &h.SampleID, &h.FromAssignmentID, &h.ToAssignmentID, &h.SenderID, &h.ReceiverID,
		&h.Status, &h.SenderConfirmed, &h.ReceiverConfirmed, &h.SenderConfirmedAt, &h.ReceiverConfirmedAt, &h.InitiatedAt, &h.CompletedAt); err != nil {
		return nil, err
	}
	return &h, nil
}

// HandoffsByReceiver returns pending/active handoffs for a worker (as sender or receiver).
func (s *Store) HandoffsByParty(ctx context.Context, userID uuid.UUID) ([]*Handoff, error) {
	rows, err := s.PG.Query(ctx, `SELECT handoff_id, sample_id, from_assignment_id, to_assignment_id, sender_id, receiver_id,
		status, sender_confirmed, receiver_confirmed, sender_confirmed_at, receiver_confirmed_at, initiated_at, completed_at
		FROM handoffs WHERE (sender_id=$1 OR receiver_id=$1) AND status='pending' ORDER BY initiated_at DESC`, userID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []*Handoff
	for rows.Next() {
		var h Handoff
		if err := rows.Scan(&h.HandoffID, &h.SampleID, &h.FromAssignmentID, &h.ToAssignmentID, &h.SenderID, &h.ReceiverID,
			&h.Status, &h.SenderConfirmed, &h.ReceiverConfirmed, &h.SenderConfirmedAt, &h.ReceiverConfirmedAt, &h.InitiatedAt, &h.CompletedAt); err != nil {
			return nil, err
		}
		out = append(out, &h)
	}
	return out, nil
}

// AllHandoffs returns every handoff.
func (s *Store) AllHandoffs(ctx context.Context) ([]*Handoff, error) {
	rows, err := s.PG.Query(ctx, `SELECT handoff_id, sample_id, from_assignment_id, to_assignment_id, sender_id, receiver_id,
		status, sender_confirmed, receiver_confirmed, sender_confirmed_at, receiver_confirmed_at, initiated_at, completed_at
		FROM handoffs ORDER BY initiated_at DESC`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []*Handoff
	for rows.Next() {
		var h Handoff
		if err := rows.Scan(&h.HandoffID, &h.SampleID, &h.FromAssignmentID, &h.ToAssignmentID, &h.SenderID, &h.ReceiverID,
			&h.Status, &h.SenderConfirmed, &h.ReceiverConfirmed, &h.SenderConfirmedAt, &h.ReceiverConfirmedAt, &h.InitiatedAt, &h.CompletedAt); err != nil {
			return nil, err
		}
		out = append(out, &h)
	}
	return out, nil
}

// ConfirmHandoffSide marks one side confirmed and finalizes the handoff when both confirm.
func (s *Store) ConfirmHandoffSide(ctx context.Context, tx pgx.Tx, id uuid.UUID, side string, at time.Time) (*Handoff, error) {
	if side == "sender" {
		_, err := tx.Exec(ctx, "UPDATE handoffs SET sender_confirmed=TRUE, sender_confirmed_at=$2 WHERE handoff_id=$1", id, at)
		if err != nil {
			return nil, err
		}
	} else {
		_, err := tx.Exec(ctx, "UPDATE handoffs SET receiver_confirmed=TRUE, receiver_confirmed_at=$2 WHERE handoff_id=$1", id, at)
		if err != nil {
			return nil, err
		}
	}
	// If both confirmed, finalize custody.
	h, err := s.HandoffByID(ctx, id)
	if err != nil {
		return nil, err
	}
	if h.SenderConfirmed && h.ReceiverConfirmed && h.Status == "pending" {
		_, err := tx.Exec(ctx, "UPDATE handoffs SET status='confirmed', completed_at=$2 WHERE handoff_id=$1", id, at)
		if err != nil {
			return nil, err
		}
		_, err = tx.Exec(ctx, "UPDATE samples SET current_holder_id=$2 WHERE sample_id=$1", h.SampleID, h.ReceiverID)
		if err != nil {
			return nil, err
		}
		_, err = tx.Exec(ctx, "UPDATE assignments SET status='completed' WHERE assignment_id=$1", h.FromAssignmentID)
		if err != nil {
			return nil, err
		}
		h.Status = "confirmed"
		h.CompletedAt = &at
	}
	return h, nil
}

// CreateCheckpoint stores a handling checkpoint.
func (s *Store) CreateCheckpoint(ctx context.Context, tx pgx.Tx, sampleID uuid.UUID, assignmentID *uuid.UUID, locationID *uuid.UUID, container string, temp *float64, compliant bool, at time.Time) (uuid.UUID, error) {
	id := uuid.New()
	_, err := tx.Exec(ctx, `INSERT INTO checkpoints (checkpoint_id, sample_id, assignment_id, location_id, container_type, observed_temperature_c, compliant, recorded_at)
		VALUES ($1,$2,$3,$4,$5,$6,$7,$8)`, id, sampleID, assignmentID, locationID, container, temp, compliant, at)
	return id, err
}

// ============================================================================
// Workers
// ============================================================================

type Worker struct {
	UserID        uuid.UUID
	Available     bool
	CapacityUnits int
	AssignedCount int
}

func (s *Store) Worker(ctx context.Context, userID uuid.UUID) (*Worker, error) {
	var w Worker
	err := s.PG.QueryRow(ctx, "SELECT user_id, worker_available, worker_capacity_units, assignment_count FROM users WHERE user_id=$1", userID).
		Scan(&w.UserID, &w.Available, &w.CapacityUnits, &w.AssignedCount)
	return &w, err
}

func (s *Store) SetWorkerAvailability(ctx context.Context, tx pgx.Tx, userID uuid.UUID, available bool, capacity int) error {
	_, err := tx.Exec(ctx, "UPDATE users SET worker_available=$2, worker_capacity_units=$3 WHERE user_id=$1", userID, available, capacity)
	return err
}

func (s *Store) RecordWorkerLocation(ctx context.Context, tx pgx.Tx, userID uuid.UUID, lat, lon float64, at time.Time) error {
	_, err := tx.Exec(ctx, "UPDATE users SET worker_latest_lat=$2, worker_latest_lon=$3, worker_location_at=$4 WHERE user_id=$1", userID, lat, lon, at)
	return err
}

// IncrementAssignmentCount bumps a worker's active assignment tally.
func (s *Store) IncrementAssignmentCount(ctx context.Context, tx pgx.Tx, userID uuid.UUID, delta int) error {
	_, err := tx.Exec(ctx, "UPDATE users SET assignment_count=assignment_count+$2 WHERE user_id=$1", userID, delta)
	return err
}

// WorkerLatestLocation returns (lat,lon,at).
func (s *Store) WorkerLatestLocation(ctx context.Context, userID uuid.UUID) (lat, lon *float64, at *time.Time, err error) {
	row := s.PG.QueryRow(ctx, "SELECT worker_latest_lat, worker_latest_lon, worker_location_at FROM users WHERE user_id=$1", userID)
	err = row.Scan(&lat, &lon, &at)
	return
}

// AllWorkers returns users that hold a worker role.
func (s *Store) AllWorkers(ctx context.Context) ([]uuid.UUID, error) {
	rows, err := s.PG.Query(ctx, `SELECT DISTINCT u.user_id FROM users u JOIN user_roles r ON r.user_id=u.user_id
		WHERE r.role IN ('collection_professional','delivery_partner','node_handler','laboratory_team') AND u.active=TRUE`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []uuid.UUID
	for rows.Next() {
		var id uuid.UUID
		_ = rows.Scan(&id)
		out = append(out, id)
	}
	return out, nil
}

// compile-time use of pgxpool to keep import
var _ = pgxpool.Config{}

