// handleConfirmHandoff confirms one side of a custody handoff.
func (s *Server) handleConfirmHandoff(w http.ResponseWriter, r *http.Request) {
	pr := principalFrom(r)
	var req struct {
		HandoffID string `json:"handoffId"`
		Side      string `json:"side"` // sender|receiver
	}
	if !decodeBody(w, r, &req) {
		return
	}
	id, err := uuid.Parse(req.HandoffID)
	if err != nil {
		writeErr(w, http.StatusBadRequest, "invalid_request", "invalid handoffId")
		return
	}
	if req.Side != "sender" && req.Side != "receiver" {
		writeErr(w, http.StatusBadRequest, "invalid_request", "side must be sender or receiver")
		return
	}
	h, err := s.Store.HandoffByID(r.Context(), id)
	if err != nil || h == nil {
		writeErr(w, http.StatusNotFound, "not_found", "handoff not found")
		return
	}
	// Only the relevant party may confirm their side.
	if req.Side == "sender" && h.SenderID != pr.User.UserID {
		writeErr(w, http.StatusForbidden, "forbidden", "not the sender")
		return
	}
	if req.Side == "receiver" && h.ReceiverID != pr.User.UserID {
		writeErr(w, http.StatusForbidden, "forbidden", "not the receiver")
		return
	}
	var updated *store.Handoff
	err = withTx(r.Context(), s.Store, func(tx pgx.Tx) error {
		hh, err := s.Store.ConfirmHandoffSide(r.Context(), tx, id, req.Side, time.Now().UTC())
		if err != nil {
