		if sm.RequesterID != pr.User.UserID {
			writeErr(w, http.StatusForbidden, "forbidden", "not your sample")
			return
		}
	}
	assignments, _ := s.Store.AssignmentsBySample(r.Context(), id)
	stops := []map[string]any{}
	journeyIDStr := ""
	if sm.ActiveJourneyID != nil {
		journeyIDStr = sm.ActiveJourneyID.String()
		st, _ := s.Store.StopsByJourney(r.Context(), *sm.ActiveJourneyID)
		for _, stp := range st {
			stops = append(stops, map[string]any{
				"locationId":   stp.LocationID.String(),
				"stopType":     stp.StopType,
				"sequence":     stp.Sequence,
				"estimatedAt":  formatTime(stp.EstimatedAt),
			})
		}
	}
