// handleRecordLaboratoryReceipt confirms laboratory receipt of a sample.
func (s *Server) handleRecordLaboratoryReceipt(w http.ResponseWriter, r *http.Request) {
	pr := principalFrom(r)
	var req struct {
		SampleID      string `json:"sampleId"`
		LaboratoryID  string `json:"laboratoryId"`
		Accepted      bool   `json:"accepted"`
		ExceptionKind  string `json:"exceptionKind"`
		ExceptionReason string `json:"exceptionReason"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	sampleID, err := uuid.Parse(req.SampleID)
	if err != nil {
		writeErr(w, http.StatusBadRequest, "invalid_request", "invalid sampleId")
		return
	}
	labID, err := uuid.Parse(req.LaboratoryID)
	if err != nil {
		writeErr(w, http.StatusBadRequest, "invalid_request", "invalid laboratoryId")
		return
	}
	err = withTx(r.Context(), s.Store, func(tx pgx.Tx) error {
		if req.Accepted {
			if err := s.Store.MarkSampleReceived(r.Context(), tx, sampleID, labID, time.Now().UTC()); err != nil {
				return err
			}
			// Complete any pending laboratory assignment.
			a, _ := s.Store.AssignmentBySampleKind(r.Context(), sampleID, "laboratory")
			if a != nil {
				_ = s.Store.UpdateAssignmentStatus(r.Context(), tx, a.AssignmentID, "completed", nil)
			}
		} else {
			kind := req.ExceptionKind
			if kind == "" {
				kind = "lab_rejected"
			}
			reason := req.ExceptionReason
			if reason == "" {
				reason = "laboratory could not accept sample"
			}
			_ = s.Store.SetSampleException(r.Context(), tx, sampleID, kind, reason)
		}
		return nil
	})
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal", "could not record receipt")
		return
	}
	s.Audit.Record(r.Context(), auditEntry(pr, "record_lab_receipt", "sample", sampleID.String(), req.Accepted, boolStr(req.Accepted)))
	s.Audit.Emit(r.Context(), audit.Event{Type: "sample.received", SampleID: sampleID.String()})
	writeData(w, http.StatusOK, map[string]any{
		"sampleId":     sampleID.String(),
		"received":     req.Accepted,
		"laboratoryId": labID.String(),
	})
}

