// handleReadSamples returns samples for dispatchers/admin or a requester's own samples.
func (s *Server) handleReadSamples(w http.ResponseWriter, r *http.Request) {
	pr := principalFrom(r)
	var req struct {
		UserId string `json:"userId"`
	}
	_ = decodeBody(w, r, &req)
	uid, err := uuid.Parse(req.UserId)
	if err != nil {
		uid = pr.User.UserID
	}
	// Requesters only see their own samples; dispatchers/admin see all.
	isPriv := pr.HasRole(string(store.RoleDispatcher)) || pr.HasRole(string(store.RoleAdministrator))
	var samples []*store.Sample
	if isPriv && req.UserId == "" {
		samples, err = s.Store.AllSamples(r.Context())
	} else {
		samples, err = s.Store.SamplesByRequester(r.Context(), uid)
	}
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal", "could not load samples")
		return
	}
	out := []map[string]any{}
	for _, sm := range samples {
		out = append(out, s.sampleSummary(sm))
	}
	writeData(w, http.StatusOK, map[string]any{"samples": out})
}

func (s *Server) sampleSummary(sm *store.Sample) map[string]any {
	m := map[string]any{
		"sampleId":           sm.SampleID.String(),
		"requestId":          sm.RequestID.String(),
		"sampleTypeId":       sm.SampleTypeID.String(),
		"originType":         sm.OriginType,
		"status":             sm.Status,
		"sealed":             sm.Sealed,
		"deliveryDeadline":   formatTime(sm.DeliveryDeadline),
		"locationStale":      sm.LocStale,
	}
	if sm.SealedAt != nil {
		m["sealedAt"] = formatTime(*sm.SealedAt)
	}
	if sm.CurrentHolderID != nil {
		m["currentHolderId"] = sm.CurrentHolderID.String()
	}
	if sm.ActiveJourneyID != nil {
		m["activeJourneyId"] = sm.ActiveJourneyID.String()
	}
	if sm.TargetLabID != nil {
		m["targetLaboratoryId"] = sm.TargetLabID.String()
	}
	if sm.ReceivedLabID != nil {
		m["receivedLaboratoryId"] = sm.ReceivedLabID.String()
	}
	if sm.LatestLat != nil && sm.LatestLon != nil {
		m["lastKnownLocation"] = map[string]any{"latitude": *sm.LatestLat, "longitude": *sm.LatestLon}
	}
	if sm.LocRecordedAt != nil {
		m["lastUpdateAt"] = formatTime(*sm.LocRecordedAt)
	}
	if sm.ExceptionKind != nil {
		m["exceptionKind"] = *sm.ExceptionKind
	}
	if sm.ExceptionReason != nil {
		m["exceptionReason"] = *sm.ExceptionReason
