	if !decodeBody(w, r, &req) {
		return
	}
	id, err := uuid.Parse(req.SampleID)
	if err != nil {
		writeErr(w, http.StatusBadRequest, "invalid_request", "invalid sampleId")
		return
	}
	sm, err := s.Store.SampleByID(r.Context(), id)
	if err != nil || sm == nil {
		writeErr(w, http.StatusNotFound, "not_found", "sample not found")
		return
	}
	assignments, _ := s.Store.AssignmentsBySample(r.Context(), id)
	checkpoints, _ := s.Store.CheckpointsBySample(r.Context(), id)
	// Audit entries for this sample.
	entries, _, _ := s.Audit.Search(r.Context(), audit.Filter{EntityType: "sample", EntityID: id.String(), Limit: 200, Order: "asc"})

	lifecycle := []map[string]any{}
	if sm.SealedAt != nil {
		lifecycle = append(lifecycle, map[string]any{"event": "sealed", "at": formatTime(*sm.SealedAt)})
	}
	for _, cp := range checkpoints {
		lifecycle = append(lifecycle, map[string]any{
			"event":       "checkpoint",
			"checkpointId": cp.CheckpointID.String(),
			"containerType": cp.ContainerType,
			"compliant":    cp.Compliant,
			"at":           formatTime(cp.RecordedAt),
		})
	}
	for _, a := range assignments {
		hist, _ := s.Store.AssignmentProgressHistory(r.Context(), a.AssignmentID)
		for _, p := range hist {
			lifecycle = append(lifecycle, map[string]any{
				"event":        "assignment_progress",
				"assignmentId": a.AssignmentID.String(),
				"kind":         a.Kind,
				"status":       p.Status,
				"note":         p.Note,
				"at":           formatTime(p.OccurredAt),
			})
		}
	}
	for _, e := range entries {
		lifecycle = append(lifecycle, map[string]any{
			"event":     "audit",
			"action":    e.Action,
			"actorId":   e.ActorID,
			"role":      e.Role,
			"at":        formatTime(e.At),
			"outcome":   e.Outcome,
		})
	}
	s.Audit.Record(r.Context(), auditEntry(pr, "read_sample_lifecycle", "sample", id.String(), true, ""))
	writeData(w, http.StatusOK, map[string]any{
		"sampleId":  id.String(),
		"status":    sm.Status,
		"lifecycle": lifecycle,
	})
}

// handleReadJourneys returns all journeys (dispatcher/admin) or for a sample.
func (s *Server) handleReadJourneys(w http.ResponseWriter, r *http.Request) {
	pr := principalFrom(r)
	var req struct {
		SampleID string `json:"sampleId"`
	}
	_ = decodeBody(w, r, &req)
	var journeys []*store.Journey
	var err error
	if req.SampleID != "" {
		id, parseErr := uuid.Parse(req.SampleID)
		if parseErr != nil {
			writeErr(w, http.StatusBadRequest, "invalid_request", "invalid sampleId")
			return
		}
		journeys, err = s.Store.JourneysBySample(r.Context(), id)
	} else {
		journeys, err = s.Store.AllJourneys(r.Context())
	}
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal", "could not load journeys")
		return
	}
	out := []map[string]any{}
	for _, j := range journeys {
		out = append(out, s.journeyView(r, j))
	}
	s.Audit.Record(r.Context(), auditEntry(pr, "read_journeys", "journey", "", true, ""))
	writeData(w, http.StatusOK, map[string]any{"journeys": out})
}

func (s *Server) journeyView(r *http.Request, j *store.Journey) map[string]any {
	m := map[string]any{
		"journeyId":   j.JourneyID.String(),
		"planVersion": j.PlanVersion,
		"routeMode":   j.RouteMode,
		"status":      j.Status,
		"valid":       j.Valid,
		"active":      j.Active,
		"totalCost":   j.TotalCost,
	}
	if j.ParentJourneyID != nil {
		m["parentJourneyId"] = j.ParentJourneyID.String()
	}
	if j.RequestID != nil {
		m["requestId"] = j.RequestID.String()
	}
	if j.EstimatedDelivery != nil {
		m["estimatedDeliveryAt"] = formatTime(*j.EstimatedDelivery)
	}
	if j.ReplanStatus != nil {
		m["replanStatus"] = *j.ReplanStatus
	}
	sids := []string{}
	for _, sid := range j.SampleIDs {
		sids = append(sids, sid.String())
	}
	m["sampleIds"] = sids
	return m
}

