// handleRecordLaboratoryReceipt confirms laboratory receipt of a sample.
func (s *Server) handleRecordLaboratoryReceipt(w http.ResponseWriter, r *http.Request) {
	pr := principalFrom(r)
	var req struct {
		SampleID      string `json:"sampleId"`
		LaboratoryID  string `json:"laboratoryId"`
		Accepted      bool   `json:"accepted"`
		ExceptionKind  string `json:"exceptionKind"`
		ExceptionReason string `json:"exceptionReason"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	sampleID, err := uuid.Parse(req.SampleID)
	if err != nil {
		writeErr(w, http.StatusBadRequest, "invalid_request", "invalid sampleId")
		return
	}
	labID, err := uuid.Parse(req.LaboratoryID)
	if err != nil {
		writeErr(w, http.StatusBadRequest, "invalid_request", "invalid laboratoryId")
		return
	}
	err = withTx(r.Context(), s.Store, func(tx pgx.Tx) error {
		if req.Accepted {
			if err := s.Store.MarkSampleReceived(r.Context(), tx, sampleID, labID, time.Now().UTC()); err != nil {
				return err
			}
			// Complete any pending laboratory assignment.
			a, _ := s.Store.AssignmentBySampleKind(r.Context(), sampleID, "laboratory")
			if a != nil {
				_ = s.Store.UpdateAssignmentStatus(r.Context(), tx, a.AssignmentID, "completed", nil)
			}
		} else {
			kind := req.ExceptionKind
			if kind == "" {
				kind = "lab_rejected"
			}
			reason := req.ExceptionReason
			if reason == "" {
				reason = "laboratory could not accept sample"
			}
			_ = s.Store.SetSampleException(r.Context(), tx, sampleID, kind, reason)
		}
		return nil
	})
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal", "could not record receipt")
		return
	}
	s.Audit.Record(r.Context(), auditEntry(pr, "record_lab_receipt", "sample", sampleID.String(), req.Accepted, boolStr(req.Accepted)))
	s.Audit.Emit(r.Context(), audit.Event{Type: "sample.received", SampleID: sampleID.String()})
	writeData(w, http.StatusOK, map[string]any{
		"sampleId":     sampleID.String(),
		"received":     req.Accepted,
		"laboratoryId": labID.String(),
	})
}

// handleReadMyWork returns current and completed work for the user's selected role.
func (s *Server) handleReadMyWork(w http.ResponseWriter, r *http.Request) {
	pr := principalFrom(r)
	assignments, err := s.Store.AssignmentsByWorker(r.Context(), pr.User.UserID)
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal", "could not load work")
		return
	}
	current := []map[string]any{}
	past := []map[string]any{}
	for _, a := range assignments {
		v := s.assignmentView(a)
		if a.Status == "completed" || a.Status == "cancelled" || a.Status == "declined" {
			past = append(past, v)
		} else {
			current = append(current, v)
		}
	}
	writeData(w, http.StatusOK, map[string]any{
		"currentWork": current,
		"pastWork":    past,
	})
}

// handleReadOperationsMonitor returns the dispatcher operations dashboard payload.
func (s *Server) handleReadOperationsMonitor(w http.ResponseWriter, r *http.Request) {
	pr := principalFrom(r)
	samples, _ := s.Store.AllSamples(r.Context())
	journeys, _ := s.Store.AllJourneys(r.Context())
	locs, _ := s.Store.AllLocations(r.Context())
	handoffs, _ := s.Store.AllHandoffs(r.Context())
	exceptions := []map[string]any{}
	monitored := []map[string]any{}
	for _, sm := range samples {
		if sm.ExceptionKind != nil {
			exceptions = append(exceptions, map[string]any{
				"sampleId":       sm.SampleID.String(),
				"exceptionKind":  *sm.ExceptionKind,
				"exceptionReason": sm.ExceptionReason,
			})
		}
		monitored = append(monitored, s.sampleSummary(sm))
	}
	locViews := []map[string]any{}
	for _, l := range locs {
		locViews = append(locViews, locationResponse(l))
	}
	journeyViews := []map[string]any{}
	for _, j := range journeys {
		journeyViews = append(journeyViews, s.journeyView(r, j))
	}
	handoffViews := []map[string]any{}
	for _, h := range handoffs {
		handoffViews = append(handoffViews, map[string]any{
			"handoffId": h.HandoffID.String(),
			"sampleId":  h.SampleID.String(),
			"status":    h.Status,
		})
	}
	s.Audit.Record(r.Context(), auditEntry(pr, "read_operations_monitor", "operations", "", true, ""))
	writeData(w, http.StatusOK, map[string]any{
		"samples":    monitored,
		"journeys":   journeyViews,
		"locations":  locViews,
		"handoffs":   handoffViews,
		"exceptions": exceptions,
	})
}

// handleReroute replans unfinished work for a sample, preserving completed legs.
func (s *Server) handleReroute(w http.ResponseWriter, r *http.Request) {
	pr := principalFrom(r)
	var req struct {
		SampleID    string `json:"sampleId"`
		PlanVersion int    `json:"planVersion"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	sampleID, err := uuid.Parse(req.SampleID)
	if err != nil {
		writeErr(w, http.StatusBadRequest, "invalid_request", "invalid sampleId")
		return
	}
	sm, err := s.Store.SampleByID(r.Context(), sampleID)
	if err != nil || sm == nil {
		writeErr(w, http.StatusNotFound, "not_found", "sample not found")
		return
	}
	// Plan-version check: ensure the client's version matches the active journey's version.
	var activeVer int
	if sm.ActiveJourneyID != nil {
		j, _ := s.Store.JourneyByID(r.Context(), *sm.ActiveJourneyID)
		if j != nil {
			activeVer = j.PlanVersion
		}
	}
	if req.PlanVersion != 0 && req.PlanVersion != activeVer {
		writeErr(w, http.StatusConflict, "plan_version_mismatch", "journey plan version changed")
		return
	}
	st, _ := s.Store.SampleTypeByID(r.Context(), sm.SampleTypeID)
	var result any
	err = withTx(r.Context(), s.Store, func(tx pgx.Tx) error {
		// Replan only unfinished assignments.
		assigns, _ := s.Store.AssignmentsBySample(r.Context(), sampleID)
		for _, a := range assigns {
			if a.Status == "completed" {
				continue
			}
			if a.Kind == "transport" {
				_ = s.Store.UpdateAssignmentStatus(r.Context(), tx, a.AssignmentID, "cancelled", nil)
			}
		}
		// Attempt a new route from the current location to the lab.
		lat, lon := sm.OriginLat, sm.OriginLon
		if sm.LatestLat != nil {
			lat = *sm.LatestLat
		}
		if sm.LatestLon != nil {
			lon = *sm.LatestLon
		}
		requiresCooled := false
		if st != nil {
			requiresCooled = st.RequiresCooledRoute
		}
		deadline := sm.DeliveryDeadline
		earliest := time.Now().UTC()
		res, err := s.Engine.PlanRoute(r.Context(), lat, lon, nil, sm.SampleTypeID, requiresCooled, earliest, deadline)
		if err != nil || !res.Serviceable {
			// Mark expired if no route can meet the deadline.
			_ = s.Store.SetSampleException(r.Context(), tx, sampleID, "expired", "no valid route meets deadline")
			result = map[string]any{"sampleId": sampleID.String(), "replanned": false, "reason": "expired"}
			return nil
		}
		newVer := activeVer + 1
		j := &store.Journey{
			PlanVersion: newVer, RouteMode: routeModeFor(res.RouteLocations), Status: "planned",
			EstimatedDelivery: &res.EstimatedArrival, TotalCost: res.TotalCost,
			SampleIDs: []uuid.UUID{sampleID}, Valid: true,
		}
		if err := s.Store.CreateJourney(r.Context(), tx, j); err != nil {
			return err
		}
		if st != nil {
			if _, err := s.buildAssignments(r.Context(), tx, j.JourneyID, sampleID, res.RouteLocations, st, sm.Sealed, nil); err != nil {
				return err
			}
		}
		_, _ = tx.Exec(r.Context(), "UPDATE samples SET active_journey_id=$2 WHERE sample_id=$1", sampleID, j.JourneyID)
		result = map[string]any{"sampleId": sampleID.String(), "journeyId": j.JourneyID.String(), "replanned": true, "planVersion": newVer}
		return nil
	})
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal", "could not reroute")
		return
	}
	s.Audit.Record(r.Context(), auditEntry(pr, "reroute", "sample", sampleID.String(), true, ""))
	writeData(w, http.StatusOK, result)
}

