package httpapi

import (
	"context"
	"encoding/json"
	"net/http"
	"strings"
	"time"

	"github.com/google/uuid"
	"github.com/labsample/app/internal/store"
)

type ctxKey string

const (
	ctxUser ctxKey = "user"
	ctxRole ctxKey = "role"
)

// Principal carries the authenticated user and selected role for a request.
type Principal struct {
	User *store.User
	Role string
}

func principalFrom(r *http.Request) *Principal {
	if v := r.Context().Value(ctxUser); v != nil {
		return v.(*Principal)
	}
	return nil
}

// authenticate middleware validates the Bearer [REDACTED] and loads the user.
func (s *Server) authenticate(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		// /ready and /api/authenticate-user and static assets are public.
		if r.URL.Path == "/ready" || r.URL.Path == "/api/authenticate-user" || r.URL.Path == "/" {
			next.ServeHTTP(w, r)
			return
		}
		if strings.HasPrefix(r.URL.Path, "/assets/") || strings.HasPrefix(r.URL.Path, "/map-assets/") || r.URL.Path == "/map-assets/style.json" {
			next.ServeHTTP(w, r)
			return
		}
		if !strings.HasPrefix(r.URL.Path, "/api/") {
			next.ServeHTTP(w, r)
			return
		}
		auth := r.Header.Get("Authorization")
		if !strings.HasPrefix(auth, "Bearer ") {
			writeErr(w, http.StatusUnauthorized, "unauthorized", "missing bearer [REDACTED]")
			return
		}
		token := strings.TrimPrefix(auth, "Bearer ")
		row := s.Store.PG.QueryRow(r.Context(), `SELECT s.user_id, s.active_role FROM sessions s
			JOIN users u ON u.user_id=s.user_id WHERE s.session_token=$1 AND s.expires_at>now() AND u.active=TRUE`, token)
		var userID uuid.UUID
		var role *string
		if err := row.Scan(&userID, &role); err != nil {
			writeErr(w, http.StatusUnauthorized, "unauthorized", "invalid or expired session")
			return
		}
		user, err := s.Store.UserByID(r.Context(), userID)
		if err != nil {
			writeErr(w, http.StatusUnauthorized, "unauthorized", "user not found")
			return
		}
		activeRole := ""
		if role != nil {
			activeRole = *role
		}
		// Default active role to first role if none selected (for non-mutating reads).
		if activeRole == "" && len(user.Roles) > 0 {
			activeRole = user.Roles[0]
		}
		pr := &Principal{User: user, Role: activeRole}
		ctx := context.WithValue(r.Context(), ctxUser, pr)
		next.ServeHTTP(w, r.WithContext(ctx))
	})
}

// requireRole returns 403 if the user lacks any of the allowed roles, or 409
// role_not_selected if they have the role but have not selected it.
func requireRole(pr *Principal, allowed ...string) (string, bool) {
	has := func(r string) bool {
		for _, rr := range pr.User.Roles {
			if rr == r {
				return true
			}
		}
		return false
	}
	for _, a := range allowed {
		if has(a) {
			if pr.Role == a {
				return a, true
			}
		}
	}
	return "", false
}

// roleGuard wraps a handler, enforcing role membership. It sets the 409/403.
func roleGuard(allowed ...string) func(http.Handler) http.Handler {
	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			pr := principalFrom(r)
			if pr == nil {
				writeErr(w, http.StatusUnauthorized, "unauthorized", "not authenticated")
				return
			}
			// Must possess at least one allowed role.
			possesses := false
			for _, a := range allowed {
				for _, rr := range pr.User.Roles {
					if rr == a {
						possesses = true
					}
				}
			}
			if !possesses {
				writeErr(w, http.StatusForbidden, "forbidden", "role not permitted")
				return
			}
			// Active role must be one of the allowed roles.
			matched := false
			for _, a := range allowed {
				if pr.Role == a {
					matched = true
				}
			}
			if !matched {
				writeErr(w, http.StatusConflict, "role_not_selected", "active role is not permitted for this action")
				return
			}
			next.ServeHTTP(w, r)
		})
	}
}

// parseTime parses an RFC3339 timestamp.
func parseTime(s string) (time.Time, bool) {
	if s == "" {
		return time.Time{}, false
	}
	t, err := time.Parse(time.RFC3339Nano, s)
	if err != nil {
		return time.Time{}, false
	}
	return t, true
}

// ptr helpers
func strPtr(s string) *string { return &s }

// decodeBody decodes a JSON body allowing optional fields.
func decodeBody(w http.ResponseWriter, r *http.Request, v any) bool {
	dec := json.NewDecoder(r.Body)
	dec.DisallowUnknownFields()
	if err := dec.Decode(v); err != nil {
		writeErr(w, http.StatusBadRequest, "invalid_json", "invalid JSON body")
		return false
	}
	return true
