for path,methods in sorted(c['paths'].items()):
    name=path.replace('/api/','')
    if name in want:
        for m,op in methods.items():
            print('===',m.upper(),path,'::',op.get('operationId'))
            rb=op.get('requestBody',{}).get('content',{}).get('application/json',{}).get('schema',{})
            print('  REQ:',json.dumps(rb))
            for code,resp in op.get('responses',{}).items():
                if code.startswith('2'):
                    sch=resp.get('content',{}).get('application/json',{}).get('schema',{})
                    print('  RES',code,':',json.dumps(sch))
" 2>&1 | head -180

