func (s *Store) CreateRequest(ctx context.Context, tx pgx.Tx, reqID, sampleID, requesterID uuid.UUID, lat, lon float64, originType string, originNode *uuid.UUID, requestedAt, deadline time.Time, earliest, latest *time.Time, sampleTypeID uuid.UUID, container string, tmin, tmax *float64, incompatible []uuid.UUID, serviceable bool, reason string, alreadySealed bool) error {
