// handleAcceptAssignment lets the offered worker accept an assignment.
func (s *Server) handleAcceptAssignment(w http.ResponseWriter, r *http.Request) {
	pr := principalFrom(r)
	var req struct {
		AssignmentID  string `json:"assignmentId"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	if req.IdempotencyKey == "" {
		writeErr(w, http.StatusBadRequest, "idempotency_required", "idempotencyKey required")
		return
	}
	id, err := uuid.Parse(req.AssignmentID)
	if err != nil {
		writeErr(w, http.StatusBadRequest, "invalid_json", "invalid assignmentId")
		return
	}
	a, err := s.Store.AssignmentByID(r.Context(), id)
	if err != nil || a == nil {
		writeErr(w, http.StatusNotFound, "not_found", "assignment not found")
		return
	}
	if a.OfferedWorkerID == nil || *a.OfferedWorkerID != pr.User.UserID {
		writeErr(w, http.StatusForbidden, "offer_not_offered", "assignment not offered to you")
		return
	}
	if a.Status != "offered" && a.Status != "pending" {
		writeErr(w, http.StatusConflict, "assignment_inactive", "assignment no longer offerable")
		return
	}
	err = withTx(r.Context(), s.Store, func(tx pgx.Tx) error {
		if err := s.Store.UpdateAssignmentStatus(r.Context(), tx, id, "accepted", &pr.User.UserID); err != nil {
			return err
		}
		if err := s.Store.IncrementAssignmentCount(r.Context(), tx, pr.User.UserID, 1); err != nil {
			return err
		}
		return s.Store.RecordAssignmentProgress(r.Context(), tx, id, "accepted", "worker accepted offer", time.Now().UTC())
	})
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", "could not accept assignment")
		return
	}
	s.Audit.Record(r.Context(), auditEntry(pr, "accept_assignment", "assignment", id.String(), true, ""))
	s.Audit.Emit(r.Context(), audit.Event{Type: "assignment.accepted", EntityType: "assignment", EntityID: id.String()})
	writeCreated(w, map[string]any{
		"assignmentId": id.String(),
		"workerId":     pr.User.UserID.String(),
		"status":       "accepted",
	})
}

// handleDeclineAssignment lets the offered worker decline and re-offers.
func (s *Server) handleDeclineAssignment(w http.ResponseWriter, r *http.Request) {
	pr := principalFrom(r)
	var req struct {
		AssignmentID   string `json:"assignmentId"`
		Reason         string `json:"reason"`
		DeclinedAt     string `json:"declinedAt"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	if req.IdempotencyKey == "" {
		writeErr(w, http.StatusBadRequest, "idempotency_required", "idempotencyKey required")
		return
	}
	id, err := uuid.Parse(req.AssignmentID)
	if err != nil {
		writeErr(w, http.StatusBadRequest, "invalid_json", "invalid assignmentId")
		return
	}
	a, err := s.Store.AssignmentByID(r.Context(), id)
	if err != nil || a == nil {
		writeErr(w, http.StatusNotFound, "not_found", "assignment not found")
		return
	}
	if a.OfferedWorkerID == nil || *a.OfferedWorkerID != pr.User.UserID {
		writeErr(w, http.StatusForbidden, "offer_not_offered", "assignment not offered to you")
		return
	}
	declinedAt, ok := parseTime(req.DeclinedAt)
	if !ok {
		declinedAt = time.Now().UTC()
	}
	reofferedTo := ""
	err = withTx(r.Context(), s.Store, func(tx pgx.Tx) error {
		_ = s.Store.RecordAssignmentProgress(r.Context(), tx, id, "declined", req.Reason, declinedAt)
		_, _ = tx.Exec(r.Context(), "UPDATE users SET decline_streak=COALESCE(decline_streak,0)+1 WHERE user_id=$1", pr.User.UserID)
		reofferedTo = s.reofferToNextWorker(r.Context(), tx, a)
		return nil
	})
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", "could not decline assignment")
		return
	}
	s.Audit.Record(r.Context(), auditEntry(pr, "decline_assignment", "assignment", id.String(), true, req.Reason))
	writeCreated(w, map[string]any{
		"assignmentId": id.String(),
		"status":       "pending",
		"declinedBy":   pr.User.UserID.String(),
		"declinedAt":   formatTime(declinedAt),
		"reofferedTo":  reofferedTo,
	})
}

// reofferToNextWorker finds the next eligible worker and re-offers; returns its id ("" if none).
func (s *Server) reofferToNextWorker(ctx context.Context, tx pgx.Tx, a *store.Assignment) string {
	workers, _ := s.Store.AllWorkers(ctx)
	st, _ := s.Store.SampleTypeByID(ctx, a.SampleID)
	prev := uuid.Nil
	if a.OfferedWorkerID != nil {
		prev = *a.OfferedWorkerID
	}
	for _, wid := range workers {
		if wid == prev {
			continue
		}
		if s.pickWorker(ctx, []uuid.UUID{wid}, a, a.Kind, st) == wid {
			_ = s.Store.ReofferAssignment(ctx, tx, a.AssignmentID, wid)
			return wid.String()
		}
	}
	_ = s.Store.SetSampleException(ctx, tx, a.SampleID, "no_qualified_worker", "declined and no other worker available")
	return ""
}

// handleCollectAndSealSample records that a sample was collected and sealed.
func (s *Server) handleCollectAndSealSample(w http.ResponseWriter, r *http.Request) {
	pr := principalFrom(r)
	var req struct {
		SampleID            string   `json:"sampleId"`
		AssignmentID        string   `json:"assignmentId"`
		CollectedAt         string   `json:"collectedAt"`
		ContainerType       string   `json:"containerType"`
		ObservedTemperatureC *float64 `json:"observedTemperatureC"`
		IdempotencyKey      string   `json:"idempotencyKey"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	if req.IdempotencyKey == "" {
		writeErr(w, http.StatusBadRequest, "idempotency_required", "idempotencyKey required")
		return
	}
	sampleID, err := uuid.Parse(req.SampleID)
	if err != nil {
		writeErr(w, http.StatusBadRequest, "invalid_json", "invalid sampleId")
		return
	}
	collectedAt, ok := parseTime(req.CollectedAt)
	if !ok {
		writeErr(w, http.StatusBadRequest, "invalid_time", "invalid collectedAt")
		return
	}
	sm, err := s.Store.SampleByID(r.Context(), sampleID)
	if err != nil || sm == nil {
		writeErr(w, http.StatusNotFound, "not_found", "sample not found")
		return
	}
	if sm.Sealed {
		writeErr(w, http.StatusConflict, "invalid_sample_state", "sample already sealed")
		return
	}
	// Collection must fall inside the collection window.
	if sm.EarliestColl != nil && collectedAt.Before(*sm.EarliestColl) {
		writeErr(w, http.StatusConflict, "outside_collection_window", "collected before earliest collection time")
		return
	}
	if sm.LatestColl != nil && collectedAt.After(*sm.LatestColl) {
		writeErr(w, http.StatusConflict, "outside_collection_window", "collected after latest collection time")
		return
	}
	st, _ := s.Store.SampleTypeByID(r.Context(), sm.SampleTypeID)
	if st != nil && st.QualifiedCollectorRequired {
		u, _ := s.Store.UserByID(r.Context(), pr.User.UserID)
		if u == nil || !hasQualification(u.Qualifications, st.RequiredQualification) {
			writeErr(w, http.StatusForbidden, "forbidden", "collector not qualified for sample type")
			return
		}
	}
	// Handling compliance against sample type container/temperature.
	compliant := true
	if st != nil {
		if req.ContainerType != "" && req.ContainerType != st.ContainerType {
			compliant = false
		}
		if req.ObservedTemperatureC != nil {
			if st.TemperatureMinC != nil && *req.ObservedTemperatureC < *st.TemperatureMinC {
				compliant = false
			}
			if st.TemperatureMaxC != nil && *req.ObservedTemperatureC > *st.TemperatureMaxC {
				compliant = false
			}
		}
	}
	var assignID *uuid.UUID
	if req.AssignmentID != "" {
		id, err := uuid.Parse(req.AssignmentID)
		if err == nil {
			assignID = &id
		}
	}
	err = withTx(r.Context(), s.Store, func(tx pgx.Tx) error {
		if err := s.Store.MarkSampleSealed(r.Context(), tx, sampleID, pr.User.UserID, collectedAt); err != nil {
			return err
		}
		if req.ContainerType != "" {
			_, _ = tx.Exec(r.Context(), "UPDATE samples SET container_type=$2 WHERE sample_id=$1", sampleID, req.ContainerType)
		}
		if assignID != nil {
			_ = s.Store.UpdateAssignmentStatus(r.Context(), tx, *assignID, "in_progress", &pr.User.UserID)
			_ = s.Store.RecordAssignmentProgress(r.Context(), tx, *assignID, "collected_sealed", "sample collected and sealed", collectedAt)
		}
		if !compliant {
			_ = s.Store.SetSampleException(r.Context(), tx, sampleID, "handling_breach", "collection container/temperature out of range")
		}
		return nil
	})
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", "could not record collection")
		return
	}
	s.Audit.Record(r.Context(), auditEntry(pr, "collect_and_seal", "sample", sampleID.String(), compliant, ""))
	s.Audit.Emit(r.Context(), audit.Event{Type: "sample.sealed", EntityType: "sample", EntityID: sampleID.String()})
	writeCreated(w, map[string]any{
		"sampleId":           sampleID.String(),
		"status":             "sealed",
		"currentHolderId":    pr.User.UserID.String(),
		"sealedAt":           formatTime(collectedAt),
		"handlingCompliant":  compliant,
	})
}

// handleRecordWorkerLocation records the worker's current location (tied to an assignment).
func (s *Server) handleRecordWorkerLocation(w http.ResponseWriter, r *http.Request) {
	pr := principalFrom(r)
	var req struct {
		AssignmentID string             `json:"assignmentId"`
		Coordinate   map[string]float64 `json:"coordinate"`
		Sequence     int                `json:"sequence"`
		RecordedAt   string             `json:"recordedAt"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	id, err := uuid.Parse(req.AssignmentID)
	if err != nil {
		writeErr(w, http.StatusBadRequest, "invalid_json", "invalid assignmentId")
		return
	}
	lat := req.Coordinate["latitude"]
	lon := req.Coordinate["longitude"]
	at, ok := parseTime(req.RecordedAt)
	if !ok {
		writeErr(w, http.StatusBadRequest, "invalid_time", "invalid recordedAt")
		return
	}
	a, err := s.Store.AssignmentByID(r.Context(), id)
	if err != nil || a == nil {
		writeErr(w, http.StatusNotFound, "not_found", "assignment not found")
		return
	}
	err = withTx(r.Context(), s.Store, func(tx pgx.Tx) error {
		if err := s.Store.RecordWorkerLocation(r.Context(), tx, pr.User.UserID, lat, lon, at); err != nil {
			return err
		}
		_ = s.Store.UpdateSampleLocation(r.Context(), tx, a.SampleID, lat, lon, at)
		_ = s.Store.RecordAssignmentProgress(r.Context(), tx, id, "in_transit", "location update", at)
		return nil
	})
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", "could not record location")
		return
	}
	s.Audit.Record(r.Context(), auditEntry(pr, "record_location", "assignment", id.String(), true, ""))
	s.Audit.Emit(r.Context(), audit.Event{Type: "worker.location", EntityType: "assignment", EntityID: id.String()})
	writeCreated(w, map[string]any{
		"assignmentId": id.String(),
		"coordinate":   map[string]any{"latitude": lat, "longitude": lon},
		"sequence":     req.Sequence,
		"recordedAt":   formatTime(at),
	})
}

// handleUpdateAssignmentProgress records a progress/status event on an assignment.
func (s *Server) handleUpdateAssignmentProgress(w http.ResponseWriter, r *http.Request) {
	pr := principalFrom(r)
	var req struct {
		AssignmentID  string `json:"assignmentId"`
		Status        string `json:"status"`
		OccurredAt    string `json:"occurredAt"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	if req.IdempotencyKey == "" {
		writeErr(w, http.StatusBadRequest, "idempotency_required", "idempotencyKey required")
		return
	}
	id, err := uuid.Parse(req.AssignmentID)
	if err != nil {
		writeErr(w, http.StatusBadRequest, "invalid_json", "invalid assignmentId")
		return
	}
	at, ok := parseTime(req.OccurredAt)
	if !ok {
		writeErr(w, http.StatusBadRequest, "invalid_time", "invalid occurredAt")
		return
	}
