	s.Audit.Emit(r.Context(), audit.Event{Type: "assignment.progress", EntityType: "assignment", EntityID: id.String()})
	writeCreated(w, map[string]any{
		"assignmentId": id.String(),
		"sampleId":     a.SampleID.String(),
		"status":       req.Status,
	})
