// handleInitiateHandoff begins a custody handoff from the current holder to a receiver.
func (s *Server) handleInitiateHandoff(w http.ResponseWriter, r *http.Request) {
	pr := principalFrom(r)
	var req struct {
		SampleID       string `json:"sampleId"`
		FromAssignmentID string `json:"fromAssignmentId"`
		ToAssignmentID string `json:"toAssignmentId"`
		ReceiverID     string `json:"receiverId"`
		InitiatedAt    string `json:"initiatedAt"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	if req.IdempotencyKey == "" {
		writeErr(w, http.StatusBadRequest, "idempotency_required", "idempotencyKey required")
		return
	}
	sampleID, err := uuid.Parse(req.SampleID)
	if err != nil {
		writeErr(w, http.StatusBadRequest, "invalid_json", "invalid sampleId")
		return
	}
	fromID, err := uuid.Parse(req.FromAssignmentID)
	if err != nil {
		writeErr(w, http.StatusBadRequest, "invalid_json", "invalid fromAssignmentId")
		return
	}
	toID, err := uuid.Parse(req.ToAssignmentID)
	if err != nil {
		writeErr(w, http.StatusBadRequest, "invalid_json", "invalid toAssignmentId")
		return
	}
	receiverID, err := uuid.Parse(req.ReceiverID)
	if err != nil {
		writeErr(w, http.StatusBadRequest, "invalid_receiver", "invalid receiverId")
		return
	}
	initiatedAt, ok := parseTime(req.InitiatedAt)
	if !ok {
		writeErr(w, http.StatusBadRequest, "invalid_time", "invalid initiatedAt")
		return
	}
	sm, err := s.Store.SampleByID(r.Context(), sampleID)
	if err != nil || sm == nil {
		writeErr(w, http.StatusNotFound, "not_found", "sample not found")
		return
	}
	if sm.CurrentHolderID == nil || *sm.CurrentHolderID != pr.User.UserID {
		writeErr(w, http.StatusConflict, "not_current_holder", "you are not the current holder")
		return
	}
	fromA, err := s.Store.AssignmentByID(r.Context(), fromID)
	if err != nil || fromA == nil || fromA.SampleID != sampleID {
		writeErr(w, http.StatusForbidden, "sender_assignment_mismatch", "from assignment does not match sample")
		return
	}
	toA, err := s.Store.AssignmentByID(r.Context(), toID)
	if err != nil || toA == nil || toA.SampleID != sampleID {
		writeErr(w, http.StatusConflict, "receiver_assignment_mismatch", "to assignment does not match sample")
		return
	}
	// No duplicate pending handoff for this sample.
	if existing, _ := s.Store.PendingHandoffForSample(r.Context(), sampleID); existing != nil {
		writeErr(w, http.StatusConflict, "pending_handoff_exists", "a pending handoff already exists")
		return
	}
	h := &store.Handoff{
		SampleID: sampleID, FromAssignmentID: fromID, ToAssignmentID: toID,
		SenderID: pr.User.UserID, ReceiverID: receiverID, InitiatedAt: initiatedAt,
	}
	err = withTx(r.Context(), s.Store, func(tx pgx.Tx) error {
		return s.Store.CreateHandoff(r.Context(), tx, h)
	})
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", "could not initiate handoff")
		return
	}
	s.Audit.Record(r.Context(), auditEntry(pr, "initiate_handoff", "handoff", h.HandoffID.String(), true, ""))
	s.Audit.Emit(r.Context(), audit.Event{Type: "handoff.initiated", EntityType: "handoff", EntityID: h.HandoffID.String()})
	writeCreated(w, map[string]any{
		"handoffId":        h.HandoffID.String(),
		"senderId":         pr.User.UserID.String(),
		"receiverId":       receiverID.String(),
		"currentHolderId":  pr.User.UserID.String(),
		"status":           "pending",
	})
}

// handleConfirmHandoff confirms one side of a custody handoff.
func (s *Server) handleConfirmHandoff(w http.ResponseWriter, r *http.Request) {
	pr := principalFrom(r)
	var req struct {
		HandoffID      string `json:"handoffId"`
		ConfirmationSide string `json:"confirmationSide"`
		ConfirmedAt    string `json:"confirmedAt"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	if req.IdempotencyKey == "" {
		writeErr(w, http.StatusBadRequest, "idempotency_required", "idempotencyKey required")
		return
	}
	id, err := uuid.Parse(req.HandoffID)
	if err != nil {
		writeErr(w, http.StatusBadRequest, "invalid_json", "invalid handoffId")
		return
	}
	if req.ConfirmationSide != "sender" && req.ConfirmationSide != "receiver" {
		writeErr(w, http.StatusBadRequest, "invalid_json", "confirmationSide must be sender or receiver")
		return
	}
	at, ok := parseTime(req.ConfirmedAt)
	if !ok {
		writeErr(w, http.StatusBadRequest, "invalid_time", "invalid confirmedAt")
		return
	}
	h, err := s.Store.HandoffByID(r.Context(), id)
	if err != nil || h == nil {
		writeErr(w, http.StatusNotFound, "not_found", "handoff not found")
		return
	}
	if req.ConfirmationSide == "sender" && h.SenderID != pr.User.UserID {
		writeErr(w, http.StatusForbidden, "forbidden", "not the sender")
		return
	}
	if req.ConfirmationSide == "receiver" && h.ReceiverID != pr.User.UserID {
		writeErr(w, http.StatusForbidden, "forbidden", "not the receiver")
		return
	}
	var updated *store.Handoff
	err = withTx(r.Context(), s.Store, func(tx pgx.Tx) error {
		hh, err := s.Store.ConfirmHandoffSide(r.Context(), tx, id, req.ConfirmationSide, at)
		if err != nil {
			return err
		}
		updated = hh
		return nil
	})
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", "could not confirm handoff")
		return
	}
	s.Audit.Record(r.Context(), auditEntry(pr, "confirm_handoff", "handoff", id.String(), true, req.ConfirmationSide))
	holderID := updated.SenderID
	if updated.Status == "confirmed" {
		holderID = updated.ReceiverID
		s.Audit.Emit(r.Context(), audit.Event{Type: "custody.transferred", EntityType: "handoff", EntityID: id.String()})
	}
	writeCreated(w, map[string]any{
		"handoffId":         id.String(),
		"status":            updated.Status,
		"senderConfirmed":   updated.SenderConfirmed,
		"receiverConfirmed": updated.ReceiverConfirmed,
		"currentHolderId":  holderID.String(),
	})
}

// handleRecordHandlingCheckpoint records a handling checkpoint for a held sample.
func (s *Server) handleRecordHandlingCheckpoint(w http.ResponseWriter, r *http.Request) {
	pr := principalFrom(r)
	var req struct {
		SampleID            string   `json:"sampleId"`
		AssignmentID        string   `json:"assignmentId"`
		LocationID          string   `json:"locationId"`
		ContainerType       string   `json:"containerType"`
		ObservedTemperatureC *float64 `json:"observedTemperatureC"`
		RecordedAt          string   `json:"recordedAt"`
		IdempotencyKey      string   `json:"idempotencyKey"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	if req.IdempotencyKey == "" {
		writeErr(w, http.StatusBadRequest, "idempotency_required", "idempotencyKey required")
		return
	}
	sampleID, err := uuid.Parse(req.SampleID)
	if err != nil {
		writeErr(w, http.StatusBadRequest, "invalid_json", "invalid sampleId")
		return
	}
	at, ok := parseTime(req.RecordedAt)
	if !ok {
		writeErr(w, http.StatusBadRequest, "invalid_time", "invalid recordedAt")
		return
	}
	sm, err := s.Store.SampleByID(r.Context(), sampleID)
	if err != nil || sm == nil {
		writeErr(w, http.StatusNotFound, "not_found", "sample not found")
		return
	}
	if sm.CurrentHolderID == nil || *sm.CurrentHolderID != pr.User.UserID {
		writeErr(w, http.StatusForbidden, "forbidden", "not the current holder")
		return
	}
	var assignID, locID *uuid.UUID
	if req.AssignmentID != "" {
		id, _ := uuid.Parse(req.AssignmentID)
		assignID = &id
	}
	if req.LocationID != "" {
		id, _ := uuid.Parse(req.LocationID)
		locID = &id
	}
	// Compliance with the sample's required container/temperature (from request overrides).
	compliant := true
	if req.ContainerType != "" && sm.ContainerType != "" && req.ContainerType != sm.ContainerType {
		compliant = false
	}
	if req.ObservedTemperatureC != nil {
		if sm.TemperatureMinC != nil && *req.ObservedTemperatureC < *sm.TemperatureMinC {
			compliant = false
		}
		if sm.TemperatureMaxC != nil && *req.ObservedTemperatureC > *sm.TemperatureMaxC {
			compliant = false
		}
	}
	var cpID uuid.UUID
	var sampleStatus string
	err = withTx(r.Context(), s.Store, func(tx pgx.Tx) error {
		id, err := s.Store.CreateCheckpoint(r.Context(), tx, sampleID, assignID, locID, req.ContainerType, req.ObservedTemperatureC, compliant, at)
		if err != nil {
			return err
		}
		cpID = id
		if !compliant {
			_ = s.Store.SetSampleException(r.Context(), tx, sampleID, "handling_breach", "checkpoint container/temperature out of range")
			sampleStatus = "exception"
		} else {
			sampleStatus = sm.Status
		}
		return nil
	})
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", "could not record checkpoint")
		return
	}
	s.Audit.Record(r.Context(), auditEntry(pr, "record_checkpoint", "checkpoint", cpID.String(), compliant, ""))
	if !compliant {
		s.Audit.Emit(r.Context(), audit.Event{Type: "sample.exception", EntityType: "sample", EntityID: sampleID.String()})
	}
	writeCreated(w, map[string]any{
		"checkpointId": cpID.String(),
		"sampleId":    sampleID.String(),
		"compliant":   compliant,
		"sampleStatus": sampleStatus,
	})
}

// handleConfirmLaboratoryReceipt confirms laboratory receipt of a sample.
func (s *Server) handleConfirmLaboratoryReceipt(w http.ResponseWriter, r *http.Request) {
	pr := principalFrom(r)
	var req struct {
		SampleID      string `json:"sampleId"`
		LaboratoryID  string `json:"laboratoryId"`
		ReceivedAt     string `json:"receivedAt"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	if req.IdempotencyKey == "" {
		writeErr(w, http.StatusBadRequest, "idempotency_required", "idempotencyKey required")
		return
	}
	sampleID, err := uuid.Parse(req.SampleID)
	if err != nil {
		writeErr(w, http.StatusBadRequest, "invalid_json", "invalid sampleId")
		return
	}
	labID, err := uuid.Parse(req.LaboratoryID)
	if err != nil {
		writeErr(w, http.StatusBadRequest, "invalid_json", "invalid laboratoryId")
		return
	}
	receivedAt, ok := parseTime(req.ReceivedAt)
	if !ok {
		writeErr(w, http.StatusBadRequest, "invalid_time", "invalid receivedAt")
		return
	}
	err = withTx(r.Context(), s.Store, func(tx pgx.Tx) error {
		if err := s.Store.MarkSampleReceived(r.Context(), tx, sampleID, labID, receivedAt); err != nil {
			return err
		}
		a, _ := s.Store.AssignmentBySampleKind(r.Context(), sampleID, "laboratory")
		if a != nil {
			_ = s.Store.UpdateAssignmentStatus(r.Context(), tx, a.AssignmentID, "completed", nil)
		}
		return nil
	})
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", "could not record receipt")
		return
	}
	s.Audit.Record(r.Context(), auditEntry(pr, "confirm_lab_receipt", "sample", sampleID.String(), true, ""))
	s.Audit.Emit(r.Context(), audit.Event{Type: "sample.received", EntityType: "sample", EntityID: sampleID.String()})
	writeCreated(w, map[string]any{
		"sampleId":     sampleID.String(),
		"laboratoryId": labID.String(),
		"status":       "received",
		"receivedAt":   formatTime(receivedAt),
	})
}

// handleRecordLaboratoryException records a laboratory exception for a sample.
func (s *Server) handleRecordLaboratoryException(w http.ResponseWriter, r *http.Request) {
	pr := principalFrom(r)
	var req struct {
		SampleID      string `json:"sampleId"`
		LaboratoryID  string `json:"laboratoryId"`
		Reason         string `json:"reason"`
		ObservedAt     string `json:"observedAt"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	if req.IdempotencyKey == "" {
		writeErr(w, http.StatusBadRequest, "idempotency_required", "idempotencyKey required")
		return
	}
	sampleID, err := uuid.Parse(req.SampleID)
	if err != nil {
		writeErr(w, http.StatusBadRequest, "invalid_json", "invalid sampleId")
		return
	}
	observedAt, ok := parseTime(req.ObservedAt)
	if !ok {
		writeErr(w, http.StatusBadRequest, "invalid_time", "invalid observedAt")
		return
	}
	exceptionID := uuid.New()
	err = withTx(r.Context(), s.Store, func(tx pgx.Tx) error {
		return s.Store.SetSampleException(r.Context(), tx, sampleID, "lab_exception", req.Reason)
	})
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", "could not record exception")
		return
	}
	s.Audit.Record(r.Context(), auditEntry(pr, "record_lab_exception", "sample", sampleID.String(), false, req.Reason))
	s.Audit.Emit(r.Context(), audit.Event{Type: "sample.exception", EntityType: "sample", EntityID: sampleID.String()})
	_ = observedAt
	writeCreated(w, map[string]any{
		"exceptionId": exceptionID.String(),
		"sampleId":    sampleID.String(),
		"status":      "exception",
		"reason":      req.Reason,
	})
}

