package httpapi

import (
	"net/http"
	"time"

	"github.com/google/uuid"
	"github.com/jackc/pgx/v5"
	"github.com/labsample/app/internal/audit"
	"github.com/labsample/app/internal/store"
)

// timelineForSample builds a TimelineEntry list from the audit log for a sample.
func (s *Server) timelineForSample(r *http.Request, sampleID uuid.UUID, order string) []map[string]any {
	entries, _, _ := s.Audit.Search(r.Context(), audit.Filter{EntityType: "sample", EntityID: sampleID.String(), Limit: 500, Order: order})
	out := []map[string]any{}
	for i, e := range entries {
		out = append(out, map[string]any{
			"eventId":     i + 1,
			"action":      e.Action,
			"actorId":     e.ActorID,
			"role":        e.Role,
			"entityType":  e.EntityType,
			"entityId":    e.EntityID,
			"success":     e.Success,
			"occurredAt":  formatTime(e.At),
			"details":     e.Changes,
		})
	}
	return out
}

// journeyPlan builds the JourneyPlan projection for a journey.
func (s *Server) journeyPlan(r *http.Request, j *store.Journey) map[string]any {
	stops, _ := s.Store.StopsByJourney(r.Context(), j.JourneyID)
	assignments, _ := s.Store.AssignmentsByJourney(r.Context(), j.JourneyID)
	stopViews := []map[string]any{}
	for _, st := range stops {
		stopViews = append(stopViews, map[string]any{
			"stopId":     st.StopID.String(),
			"locationId": st.LocationID.String(),
			"stopType":   st.StopType,
			"sequence":   st.Sequence,
			"estimatedAt": formatTime(st.EstimatedAt),
		})
	}
	legViews := []map[string]any{}
	var collectionIDs, nodeIDs, labIDs []string
	assignedWorkers := []string{}
	firstTransport := ""
	finalTransport := ""
	capUsed := 0
	for _, a := range assignments {
		legViews = append(legViews, assignmentLeg(a))
		if a.Kind == "collection" {
			collectionIDs = append(collectionIDs, a.AssignmentID.String())
		}
		if a.Kind == "node" {
			nodeIDs = append(nodeIDs, a.AssignmentID.String())
		}
		if a.Kind == "laboratory" {
			labIDs = append(labIDs, a.AssignmentID.String())
		}
		if a.WorkerID != nil {
			assignedWorkers = append(assignedWorkers, a.WorkerID.String())
		}
		if a.Kind == "transport" {
			if firstTransport == "" {
				firstTransport = a.AssignmentID.String()
			}
			finalTransport = a.AssignmentID.String()
			capUsed++
		}
	}
	sids := []string{}
	for _, sid := range j.SampleIDs {
		sids = append(sids, sid.String())
	}
	m := map[string]any{
		"journeyId":               j.JourneyID.String(),
		"planVersion":             j.PlanVersion,
		"routeMode":              j.RouteMode,
		"status":                 j.Status,
		"sampleIds":              sids,
		"orderedStops":           stopViews,
		"legs":                   legViews,
		"valid":                  j.Valid,
		"totalCostUnits":         j.TotalCost,
		"capacityUsed":           capUsed,
		"assignedWorkerIds":       assignedWorkers,
		"collectionAssignmentIds": collectionIDs,
		"nodeAssignmentIds":       nodeIDs,
		"laboratoryAssignmentIds": labIDs,
		"firstTransportAssignmentId": firstTransport,
		"finalTransportAssignmentId":  finalTransport,
	}
	if j.ParentJourneyID != nil {
		m["parentJourneyId"] = j.ParentJourneyID.String()
	}
	if j.EstimatedDelivery != nil {
		m["estimatedDeliveryAt"] = formatTime(*j.EstimatedDelivery)
	}
	if j.ReplanStatus != nil {
		m["replanStatus"] = *j.ReplanStatus
	}
	return m
}

// handleReadJourneyPlan returns the plan for a journey (full / requester / worker scoped).
func (s *Server) handleReadJourneyPlan(w http.ResponseWriter, r *http.Request) {
	pr := principalFrom(r)
	var req struct {
		JourneyID string `json:"journeyId"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	id, err := uuid.Parse(req.JourneyID)
	if err != nil {
		writeErr(w, http.StatusBadRequest, "invalid_json", "invalid journeyId")
		return
	}
	j, err := s.Store.JourneyByID(r.Context(), id)
	if err != nil || j == nil {
		writeErr(w, http.StatusNotFound, "not_found", "journey not found")
		return
	}
	plan := s.journeyPlan(r, j)
	// Worker scope: only their assigned legs.
	if pr.HasRole(RoleCollectionProfessional) || pr.HasRole(RoleDeliveryPartner) || pr.HasRole(RoleNodeHandler) || pr.HasRole(RoleLaboratoryTeam) {
		assignments, _ := s.Store.AssignmentsByJourney(r.Context(), id)
		var myLegs []map[string]any
		var myIDs []string
		for _, a := range assignments {
			if (a.WorkerID != nil && *a.WorkerID == pr.User.UserID) || (a.OfferedWorkerID != nil && *a.OfferedWorkerID == pr.User.UserID) {
				myLegs = append(myLegs, assignmentLeg(a))
				myIDs = append(myIDs, a.AssignmentID.String())
			}
		}
		writeData(w, http.StatusOK, map[string]any{
			"journeyId":         j.JourneyID.String(),
			"planVersion":       j.PlanVersion,
			"routeMode":         j.RouteMode,
			"status":            j.Status,
			"scope":             "assigned_legs",
			"assignmentIds":     myIDs,
			"legs":              myLegs,
			"orderedStops":      plan["orderedStops"],
			"sampleIds":         plan["sampleIds"],
		})
		return
	}
	// Requester scope: simplified.
	if pr.HasRole(RoleRequester) {
		writeData(w, http.StatusOK, map[string]any{
			"journeyId":          j.JourneyID.String(),
			"planVersion":        j.PlanVersion,
			"routeMode":          j.RouteMode,
			"status":             j.Status,
			"sampleIds":          plan["sampleIds"],
			"orderedStops":       plan["orderedStops"],
			"legs":               []map[string]any{},
		})
		return
	}
	writeData(w, http.StatusOK, plan)
}

// handleSplitJourney splits selected samples into a new journey (plan-version checked).
func (s *Server) handleSplitJourney(w http.ResponseWriter, r *http.Request) {
	pr := principalFrom(r)
	var req struct {
		JourneyID          string   `json:"journeyId"`
		ExpectedPlanVersion int     `json:"expectedPlanVersion"`
		SampleIDs          []string `json:"sampleIds"`
		IdempotencyKey     string   `json:"idempotencyKey"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	if req.IdempotencyKey == "" {
		writeErr(w, http.StatusBadRequest, "idempotency_required", "idempotencyKey required")
		return
	}
	jid, err := uuid.Parse(req.JourneyID)
	if err != nil {
		writeErr(w, http.StatusBadRequest, "invalid_json", "invalid journeyId")
		return
	}
	j, err := s.Store.JourneyByID(r.Context(), jid)
	if err != nil || j == nil {
		writeErr(w, http.StatusNotFound, "not_found", "journey not found")
		return
	}
	if j.PlanVersion != req.ExpectedPlanVersion {
		writeErr(w, http.StatusConflict, "stale_plan", "journey plan version changed")
		return
	}
	var splitIDs []uuid.UUID
	for _, sid := range req.SampleIDs {
		id, err := uuid.Parse(sid)
		if err != nil {
			writeErr(w, http.StatusBadRequest, "invalid_json", "invalid sampleIds")
			return
		}
		splitIDs = append(splitIDs, id)
	}
	var split *store.Journey
	err = withTx(r.Context(), s.Store, func(tx pgx.Tx) error {
		parent := j.JourneyID
		split = &store.Journey{
			ParentJourneyID: &parent, PlanVersion: 1, RouteMode: j.RouteMode, Status: "planned",
			EstimatedDelivery: j.EstimatedDelivery, TotalCost: j.TotalCost, SampleIDs: splitIDs, Valid: true,
		}
		if err := s.Store.CreateJourney(r.Context(), tx, split); err != nil {
			return err
		}
		return nil
	})
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", "could not split journey")
		return
	}
	s.Audit.Record(r.Context(), auditEntry(pr, "split_journey", "journey", split.JourneyID.String(), true, ""))
	writeCreated(w, map[string]any{
		"journey":     s.journeyPlan(r, j),
		"splitJourney": s.journeyPlan(r, split),
	})
}

// handleMergeJourneys merges source journeys into a target (plan-version checked).
func (s *Server) handleMergeJourneys(w http.ResponseWriter, r *http.Request) {
	pr := principalFrom(r)
	var req struct {
		TargetJourneyID    string   `json:"targetJourneyId"`
		ExpectedPlanVersion int     `json:"expectedPlanVersion"`
		SourceJourneyIDs   []string `json:"sourceJourneyIds"`
		IdempotencyKey     string   `json:"idempotencyKey"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	if req.IdempotencyKey == "" {
		writeErr(w, http.StatusBadRequest, "idempotency_required", "idempotencyKey required")
		return
	}
	tid, err := uuid.Parse(req.TargetJourneyID)
	if err != nil {
		writeErr(w, http.StatusBadRequest, "invalid_json", "invalid targetJourneyId")
		return
	}
	j, err := s.Store.JourneyByID(r.Context(), tid)
	if err != nil || j == nil {
		writeErr(w, http.StatusNotFound, "not_found", "journey not found")
		return
	}
	if j.PlanVersion != req.ExpectedPlanVersion {
		writeErr(w, http.StatusConflict, "stale_plan", "journey plan version changed")
		return
	}
	mergedIDs := append([]uuid.UUID{}, j.SampleIDs...)
	for _, sid := range req.SourceJourneyIDs {
		id, err := uuid.Parse(sid)
		if err != nil {
			writeErr(w, http.StatusBadRequest, "invalid_json", "invalid sourceJourneyIds")
			return
		}
		sj, _ := s.Store.JourneyByID(r.Context(), id)
		if sj != nil {
			mergedIDs = append(mergedIDs, sj.SampleIDs...)
