// role wrappers ---------------------------------------------------------------

func (s *Server) adminOnly(h http.HandlerFunc) http.HandlerFunc {
	return roleGuard(RoleAdministrator)(h).ServeHTTP
}
func (s *Server) adminOrDispatcher(h http.HandlerFunc) http.HandlerFunc {
	return roleGuard(RoleAdministrator, RoleDispatcher)(h).ServeHTTP
}
func (s *Server) dispatcherOnly(h http.HandlerFunc) http.HandlerFunc {
	return roleGuard(RoleDispatcher, RoleAdministrator)(h).ServeHTTP
}
func (s *Server) dispatcherOrAdmin(h http.HandlerFunc) http.HandlerFunc {
	return roleGuard(RoleDispatcher, RoleAdministrator)(h).ServeHTTP
}
func (s *Server) requesterOnly(h http.HandlerFunc) http.HandlerFunc {
	return roleGuard(RoleRequester)(h).ServeHTTP
}
func (s *Server) requesterOrDispatcher(h http.HandlerFunc) http.HandlerFunc {
	return roleGuard(RoleRequester, RoleDispatcher, RoleAdministrator)(h).ServeHTTP
}
func (s *Server) collectionProOnly(h http.HandlerFunc) http.HandlerFunc {
	return roleGuard(RoleCollectionProfessional)(h).ServeHTTP
}
func (s *Server) deliveryOnly(h http.HandlerFunc) http.HandlerFunc {
	return roleGuard(RoleDeliveryPartner)(h).ServeHTTP
}
func (s *Server) nodeHandlerOnly(h http.HandlerFunc) http.HandlerFunc {
	return roleGuard(RoleNodeHandler)(h).ServeHTTP
}
func (s *Server) labOnly(h http.HandlerFunc) http.HandlerFunc {
	return roleGuard(RoleLaboratoryTeam)(h).ServeHTTP
}
func (s *Server) workerOnly(h http.HandlerFunc) http.HandlerFunc {
	return roleGuard(RoleCollectionProfessional, RoleDeliveryPartner, RoleNodeHandler, RoleLaboratoryTeam)(h).ServeHTTP
}
func (s *Server) workerOrDispatcher(h http.HandlerFunc) http.HandlerFunc {
	return roleGuard(RoleCollectionProfessional, RoleDeliveryPartner, RoleNodeHandler, RoleLaboratoryTeam, RoleDispatcher, RoleAdministrator)(h).ServeHTTP
}

// authed requires a valid authenticated principal but no specific role.
// The active role may be empty for reads that don't need a selected role.
func (s *Server) authed(h http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		if principalFrom(r) == nil {
			writeErr(w, http.StatusUnauthorized, "unauthorized", "not authenticated")
			return
		}
		h(w, r)
	}
}

// Role constants local to this package (mirroring store roles for guard usage).
const (
	RoleAdministrator         = "administrator"
	RoleDispatcher            = "dispatcher"
	RoleRequester             = "requester"
	RoleCollectionProfessional = "collection_professional"
	RoleDeliveryPartner       = "delivery_partner"
	RoleNodeHandler           = "node_handler"
	RoleLaboratoryTeam        = "laboratory_team"
