// ResetSchema fully materializes a clean application state: it recreates the
// Postgres schema and Mongo collections/indexes. Safe to run repeatedly; the
// application must be stopped when called.
func ResetSchema(ctx context.Context, pg *pgxpool.Pool, mc *mongo.Client, dbName string) error {
	// Drop all application tables in dependency order, then recreate.
	drop := []string{
		"checkpoints", "handoffs", "assignment_progress", "capacity_reservations",
		"stops", "assignments", "journeys", "samples", "requests",
		"disruptions", "serviceability_snapshots", "idempotency",
		"laboratory_acceptance", "capacity", "connections", "locations",
		"sample_types", "certifications", "qualifications", "user_roles",
		"sessions", "users",
	}
	for _, t := range drop {
		if _, err := pg.Exec(ctx, "DROP TABLE IF EXISTS "+t+" CASCADE"); err != nil {
			return err
		}
	}
	if err := Migrate(ctx, pg); err != nil {
		return err
	}
	if err := resetMongo(ctx, mc, dbName); err != nil {
		return err
	}
	return nil
}

func resetMongo(ctx context.Context, mc *mongo.Client, dbName string) error {
	db := mc.Database(dbName)
	// Materialize collections explicitly (Mongo would otherwise create them lazily).
	for _, name := range MongoCollections {
		if err := db.CreateCollection(ctx, name); err != nil {
			// Already exists: drop and recreate to guarantee clean state.
			if err2 := db.Collection(name).Drop(ctx); err2 != nil {
				return err2
			}
			if err2 := db.CreateCollection(ctx, name); err2 != nil {
				return err2
			}
		}
	}
	// Indexes.
	if err := ensureMongoIndexes(ctx, db); err != nil {
		return err
	}
	return nil
}

// MongoCollections is the full set of Mongo collections the app uses.
var MongoCollections = []string{
	"audit_log",
	"realtime_events",
}

func ensureMongoIndexes(ctx context.Context, db *mongo.Database) error {
	models := []mongo.IndexModel{
		{Keys: bson.D{{Key: "entityType", Value: 1}, {Key: "entityId", Value: 1}}},
		{Keys: bson.D{{Key: "actorId", Value: 1}}},
		{Keys: bson.D{{Key: "action", Value: 1}}},
		{Keys: bson.D{{Key: "role", Value: 1}}},
		{Keys: bson.D{{Key: "at", Value: -1}}},
	}
	if _, err := db.Collection("audit_log").Indexes().CreateMany(ctx, models); err != nil {
		return err
	}
	_, err := db.Collection("realtime_events").Indexes().CreateMany(ctx, []mongo.IndexModel{
		{Keys: bson.D{{Key: "seq", Value: 1}}},
		{Keys: bson.D{{Key: "sampleId", Value: 1}}},
	})
	return err
}

