package httpapi

import (
	"net/http"

	"github.com/google/uuid"
	"github.com/jackc/pgx/v5"
	"github.com/labsample/app/internal/store"
)

// handleCreateLocation (admin).
func (s *Server) handleCreateLocation(w http.ResponseWriter, r *http.Request) {
	pr := principalFrom(r)
	var req struct {
		Name            string         `json:"name"`
		Coordinate      map[string]float64 `json:"coordinate"`
		CoverageKm      *float64       `json:"coverageKm"`
		HandlingMinutes *int           `json:"handlingMinutes"`
		Active          bool           `json:"active"`
		Functions       []string       `json:"functions"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	if req.Name == "" || req.Coordinate == nil {
		writeErr(w, http.StatusBadRequest, "invalid_request", "name and coordinate required")
		return
	}
	lat := req.Coordinate["latitude"]
	lon := req.Coordinate["longitude"]
	coverage := 5.0
	if req.CoverageKm != nil {
		coverage = *req.CoverageKm
	}
	handling := 0
	if req.HandlingMinutes != nil {
		handling = *req.HandlingMinutes
	}
	fns := parseFns(req.Functions)
	var loc *store.Location
	err := withTx(r.Context(), s.Store, func(tx pgx.Tx) error {
		l, err := s.Store.CreateLocation(r.Context(), tx, req.Name, lat, lon, coverage, handling, req.Active, fns)
		if err != nil {
			return err
		}
		loc = l
		return nil
	})
	if err != nil {
		writeErr(w, http.StatusConflict, "conflict", "could not create location")
		return
	}
	s.Audit.Record(r.Context(), auditEntry(pr, "create_location", "location", loc.LocationID.String(), true, ""))
	writeCreated(w, locationResponse(loc))
}

// handleUpdateLocation (admin).
func (s *Server) handleUpdateLocation(w http.ResponseWriter, r *http.Request) {
	pr := principalFrom(r)
	var req struct {
		LocationID      string         `json:"locationId"`
		Name            string         `json:"name"`
		Coordinate      map[string]float64 `json:"coordinate"`
		CoverageKm      *float64       `json:"coverageKm"`
		HandlingMinutes *int           `json:"handlingMinutes"`
		Functions       []string       `json:"functions"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	id, err := uuid.Parse(req.LocationID)
	if err != nil {
		writeErr(w, http.StatusBadRequest, "invalid_request", "invalid locationId")
		return
	}
	lat := req.Coordinate["latitude"]
	lon := req.Coordinate["longitude"]
	coverage := 5.0
	if req.CoverageKm != nil {
		coverage = *req.CoverageKm
	}
	handling := 0
	if req.HandlingMinutes != nil {
		handling = *req.HandlingMinutes
	}
	fns := parseFns(req.Functions)
	err = withTx(r.Context(), s.Store, func(tx pgx.Tx) error {
		return s.Store.UpdateLocation(r.Context(), tx, id, req.Name, lat, lon, coverage, handling, fns)
	})
	if err != nil {
		writeErr(w, http.StatusNotFound, "not_found", "location not found")
		return
	}
	loc, _ := s.Store.LocationByID(r.Context(), id)
	if loc == nil {
		writeErr(w, http.StatusNotFound, "not_found", "location not found")
		return
	}
	s.Audit.Record(r.Context(), auditEntry(pr, "update_location", "location", id.String(), true, ""))
	writeCreated(w, locationResponse(loc))
}

// handleSetLocationStatus (admin).
func (s *Server) handleSetLocationStatus(w http.ResponseWriter, r *http.Request) {
	pr := principalFrom(r)
	var req struct {
		LocationID string `json:"locationId"`
		Active     bool   `json:"active"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	id, err := uuid.Parse(req.LocationID)
	if err != nil {
		writeErr(w, http.StatusBadRequest, "invalid_request", "invalid locationId")
		return
	}
	err = withTx(r.Context(), s.Store, func(tx pgx.Tx) error {
		return s.Store.SetLocationStatus(r.Context(), tx, id, req.Active)
	})
	if err != nil {
		writeErr(w, http.StatusNotFound, "not_found", "location not found")
		return
	}
	s.Audit.Record(r.Context(), auditEntry(pr, "set_location_status", "location", id.String(), true, ""))
	writeData(w, http.StatusOK, map[string]any{"locationId": id.String(), "active": req.Active})
}

// handleSetLocationFunctionStatus (admin).
func (s *Server) handleSetLocationFunctionStatus(w http.ResponseWriter, r *http.Request) {
	pr := principalFrom(r)
	var req struct {
		LocationID string `json:"locationId"`
		Function  string `json:"function"`
		Active    bool   `json:"active"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	id, err := uuid.Parse(req.LocationID)
	if err != nil {
		writeErr(w, http.StatusBadRequest, "invalid_request", "invalid locationId")
		return
	}
	var fns store.LocationFunction
	err = withTx(r.Context(), s.Store, func(tx pgx.Tx) error {
		f, err := s.Store.SetLocationFunctionStatus(r.Context(), tx, id, req.Function, req.Active)
		if err != nil {
			return err
		}
		fns = f
		return nil
	})
	if err != nil {
		writeErr(w, http.StatusNotFound, "not_found", "location not found")
		return
	}
	s.Audit.Record(r.Context(), auditEntry(pr, "set_location_function_status", "location", id.String(), true, "fn="+req.Function))
	writeData(w, http.StatusOK, map[string]any{
		"locationId": id.String(),
		"function":   req.Function,
		"active":     req.Active,
		"functions":  fnStates(fns),
	})
}

// handleCreateConnection (admin).
func (s *Server) handleCreateConnection(w http.ResponseWriter, r *http.Request) {
	pr := principalFrom(r)
	var req struct {
		FromLocationID string  `json:"fromLocationId"`
		ToLocationID   string  `json:"toLocationId"`
		TravelMinutes  int     `json:"travelMinutes"`
		CostUnits      float64 `json:"costUnits"`
		Cooled         bool    `json:"cooled"`
		Active         bool    `json:"active"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	from, err := uuid.Parse(req.FromLocationID)
	if err != nil {
		writeErr(w, http.StatusBadRequest, "invalid_request", "invalid fromLocationId")
		return
