package main

import (
	"context"
	"fmt"
	"log"
	"net/http"
	"os"
	"os/signal"
	"syscall"
	"time"

	"github.com/google/uuid"
	"github.com/jackc/pgx/v5"
	"github.com/labsample/app/internal/auth"
	"github.com/labsample/app/internal/db"
	"github.com/labsample/app/internal/httpapi"
	"github.com/labsample/app/internal/store"
)

func main() {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	conns, err := db.Connect(ctx)
	if err != nil {
		log.Fatalf("connect datastores: %v", err)
	}
	defer conns.PG.Close()
	defer conns.Mongo.Disconnect(ctx)

	// Apply schema on startup (idempotent).
	if err := db.Migrate(ctx, conns.PG); err != nil {
		log.Fatalf("migrate: %v", err)
	}

	st := store.New(conns.PG)
	mdb := conns.Mongo.Database(conns.DbName)

	// Seed default sample types if none exist.
	if err := seedSampleTypes(ctx, st); err != nil {
		log.Printf("seed sample types: %v", err)
	}

	// Ensure initial admin from env (only when no users exist).
	if err := ensureInitialAdmin(ctx, st); err != nil {
		log.Printf("ensure initial admin: %v", err)
	}

	srv := httpapi.New(st, mdb)

	addr := os.Getenv("APP_ADDR")
	if addr == "" {
		addr = "127.0.0.1:8080"
	}
	httpSrv := &http.Server{
		Addr:    addr,
		Handler: srv.Handler(),
		ReadHeaderTimeout: 10 * time.Second,
	}

	go func() {
		log.Printf("listening on %s", addr)
		if err := httpSrv.ListenAndServe(); err != nil && err != http.ErrServerClosed {
			log.Fatalf("server: %v", err)
		}
	}()

	sigc := make(chan os.Signal, 1)
	signal.Notify(sigc, syscall.SIGINT, syscall.SIGTERM)
	<-sigc
	shutCtx, shutCancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer shutCancel()
	_ = httpSrv.Shutdown(shutCtx)
}

func seedSampleTypes(ctx context.Context, st *store.Store) error {
	types, err := st.AllSampleTypes(ctx)
	if err != nil {
		return err
	}
	if len(types) > 0 {
		return nil
	}
	tx, err := st.PG.BeginTx(ctx, pgx.TxOptions{})
	if err != nil {
		return err
	}
	defer tx.Rollback(ctx)
	if err := st.SeedDefaultSampleTypes(ctx, tx); err != nil {
		return err
	}
	return tx.Commit(ctx)
}

// ensureInitialAdmin creates the first administrator account from
// ADMIN_USERNAME/ADMIN_PASSWORD when no users exist yet.
func ensureInitialAdmin(ctx context.Context, st *store.Store) error {
	has, err := st.HasAnyUsers(ctx)
	if err != nil {
		return err
	}
	if has {
		return nil
	}
	username := os.Getenv("ADMIN_USERNAME")
	password := os.Getenv("ADMIN_PASSWORD")
	if username == "" || password == "" {
		return fmt.Errorf("ADMIN_USERNAME/ADMIN_PASSWORD not set and no users exist")
	}
	hash, err := auth.HashPassword(password)
	if err != nil {
		return err
	}
	u := &store.User{
		Username: username,
		Roles:    []string{string(store.RoleAdministrator)},
		Active:   true,
	}
	tx, err := st.PG.BeginTx(ctx, pgx.TxOptions{})
	if err != nil {
		return err
	}
	defer tx.Rollback(ctx)
	if err := st.CreateUser(ctx, tx, u, hash); err != nil {
		return err
	}
	if _, err := tx.Exec(ctx, "UPDATE users SET is_admin=TRUE WHERE user_id=$1", u.UserID); err != nil {
		return err
	}
	if err := tx.Commit(ctx); err != nil {
		return err
	}
	log.Printf("created initial administrator %s (id=%s)", u.Username, u.UserID)
	_ = uuid.Nil
	return nil
}

