package httpapi

import (
	"net/http"

	"github.com/labsample/app/internal/audit"
	"github.com/labsample/app/internal/serviceability"
	"github.com/labsample/app/internal/store"
	"go.mongodb.org/mongo-driver/mongo"
)

// Server holds application dependencies wired into HTTP handlers.
type Server struct {
	Store   *store.Store
	Mongo   *mongo.Database
	Audit   *audit.Store
	Engine  *serviceability.Engine
	Snap    *serviceability.SnapshotManager
	Mux     *http.ServeMux
}

// New constructs a Server with all dependencies.
func New(s *store.Store, mdb *mongo.Database) *Server {
	srv := &Server{
		Store: s,
		Mongo: mdb,
		Audit: audit.New(mdb),
		Engine: serviceability.New(s),
		Snap:   serviceability.NewSnapshotManager(s),
		Mux:    http.NewServeMux(),
	}
	srv.registerRoutes()
	return srv
}

// routes returns the HTTP mux.
func (s *Server) routes() http.Handler {
	return s.Mux
}

// Handler returns the root HTTP handler, applying authentication middleware.
func (s *Server) Handler() http.Handler {
	return s.authenticate(s.Mux)
}

func (s *Server) registerRoutes() {
	m := s.Mux

	// Public
	m.HandleFunc("GET /ready", s.handleReady)
	m.HandleFunc("POST /api/authenticate-user", s.handleAuthenticate)

	// Authenticated
	m.HandleFunc("POST /api/select-active-role", s.authed(s.handleSelectActiveRole))
	m.HandleFunc("GET /api/ui/bootstrap", s.authed(s.handleReadUIBootstrap))
	m.HandleFunc("GET /api/read-user/{userId}", s.authed(s.handleReadUser))

	// Users / access (admin)
	m.HandleFunc("POST /api/create-user", s.adminOnly(s.handleCreateUser))
	m.HandleFunc("POST /api/update-user-access", s.adminOnly(s.handleUpdateUserAccess))
	m.HandleFunc("POST /api/set-worker-availability", s.adminOrDispatcher(s.handleSetWorkerAvailability))

	// Network config (admin)
	m.HandleFunc("POST /api/create-location", s.adminOnly(s.handleCreateLocation))
	m.HandleFunc("POST /api/update-location", s.adminOnly(s.handleUpdateLocation))
	m.HandleFunc("POST /api/set-location-status", s.adminOnly(s.handleSetLocationStatus))
	m.HandleFunc("POST /api/set-location-function-status", s.adminOnly(s.handleSetLocationFunctionStatus))
	m.HandleFunc("POST /api/create-connection", s.adminOnly(s.handleCreateConnection))
	m.HandleFunc("POST /api/set-connection-status", s.adminOnly(s.handleSetConnectionStatus))
	m.HandleFunc("POST /api/create-sample-type", s.adminOnly(s.handleCreateSampleType))
	m.HandleFunc("POST /api/update-sample-type", s.adminOnly(s.handleUpdateSampleType))
	m.HandleFunc("POST /api/configure-laboratory-acceptance", s.adminOnly(s.handleConfigureLaboratoryAcceptance))
	m.HandleFunc("POST /api/configure-capacity", s.adminOrDispatcher(s.handleConfigureCapacity))

	// Serviceability
	m.HandleFunc("POST /api/check-serviceability", s.requesterOrDispatcher(s.handleCheckServiceability))
	m.HandleFunc("POST /api/read-serviceability-snapshot", s.authed(s.handleReadServiceabilitySnapshot))

	// Requests & samples
	m.HandleFunc("POST /api/create-collection-request", s.requesterOnly(s.handleCreateCollectionRequest))
	m.HandleFunc("POST /api/ingest-presealed-sample", s.workerOrDispatcher(s.handleIngestPresealedSample))
	m.HandleFunc("GET /api/read-sample-state/{sampleId}", s.authed(s.handleReadSampleState))
	m.HandleFunc("POST /api/read-sample-lifecycle", s.authed(s.handleReadSampleLifecycle))

	// Journeys & planning (dispatcher/admin)
	m.HandleFunc("POST /api/read-journey-plan", s.authed(s.handleReadJourneyPlan))
	m.HandleFunc("POST /api/split-journey", s.dispatcherOnly(s.handleSplitJourney))
	m.HandleFunc("POST /api/merge-journeys", s.dispatcherOnly(s.handleMergeJourneys))
	m.HandleFunc("POST /api/reroute-journey", s.dispatcherOnly(s.handleRerouteJourney))
	m.HandleFunc("POST /api/cancel-journey", s.dispatcherOnly(s.handleCancelJourney))
	m.HandleFunc("POST /api/edit-active-plan", s.dispatcherOnly(s.handleEditActivePlan))
	m.HandleFunc("POST /api/report-disruption", s.dispatcherOnly(s.handleReportDisruption))
	m.HandleFunc("POST /api/read-operations-state", s.dispatcherOnly(s.handleReadOperationsState))

	// Work & assignments
	m.HandleFunc("POST /api/list-role-work", s.authed(s.handleListRoleWork))
	m.HandleFunc("POST /api/accept-assignment", s.workerOnly(s.handleAcceptAssignment))
	m.HandleFunc("POST /api/decline-assignment", s.workerOnly(s.handleDeclineAssignment))
	m.HandleFunc("POST /api/collect-and-seal-sample", s.collectionProOnly(s.handleCollectAndSealSample))
	m.HandleFunc("POST /api/update-assignment-progress", s.deliveryOnly(s.handleUpdateAssignmentProgress))
	m.HandleFunc("POST /api/record-worker-location", s.workerOnly(s.handleRecordWorkerLocation))
	m.HandleFunc("POST /api/initiate-handoff", s.workerOnly(s.handleInitiateHandoff))
	m.HandleFunc("POST /api/confirm-handoff", s.workerOnly(s.handleConfirmHandoff))
	m.HandleFunc("POST /api/record-handling-checkpoint", s.workerOnly(s.handleRecordHandlingCheckpoint))
	m.HandleFunc("POST /api/confirm-laboratory-receipt", s.labOnly(s.handleConfirmLaboratoryReceipt))
	m.HandleFunc("POST /api/record-laboratory-exception", s.labOnly(s.handleRecordLaboratoryException))

	// Audit & realtime
	m.HandleFunc("POST /api/search-audit-trail", s.dispatcherOrAdmin(s.handleSearchAuditTrail))
	m.HandleFunc("GET /api/events", s.authed(s.handleStreamRealtimeEvents))
}

// role wrappers ---------------------------------------------------------------

func (s *Server) adminOnly(h http.HandlerFunc) http.HandlerFunc {
	return roleGuard(RoleAdministrator)(h).ServeHTTP
}
func (s *Server) adminOrDispatcher(h http.HandlerFunc) http.HandlerFunc {
	return roleGuard(RoleAdministrator, RoleDispatcher)(h).ServeHTTP
}
func (s *Server) dispatcherOnly(h http.HandlerFunc) http.HandlerFunc {
	return roleGuard(RoleDispatcher, RoleAdministrator)(h).ServeHTTP
}
func (s *Server) dispatcherOrAdmin(h http.HandlerFunc) http.HandlerFunc {
	return roleGuard(RoleDispatcher, RoleAdministrator)(h).ServeHTTP
}
func (s *Server) requesterOnly(h http.HandlerFunc) http.HandlerFunc {
	return roleGuard(RoleRequester)(h).ServeHTTP
}
func (s *Server) requesterOrDispatcher(h http.HandlerFunc) http.HandlerFunc {
	return roleGuard(RoleRequester, RoleDispatcher, RoleAdministrator)(h).ServeHTTP
}
func (s *Server) collectionProOnly(h http.HandlerFunc) http.HandlerFunc {
	return roleGuard(RoleCollectionProfessional)(h).ServeHTTP
}
func (s *Server) deliveryOnly(h http.HandlerFunc) http.HandlerFunc {
	return roleGuard(RoleDeliveryPartner)(h).ServeHTTP
}
func (s *Server) nodeHandlerOnly(h http.HandlerFunc) http.HandlerFunc {
	return roleGuard(RoleNodeHandler)(h).ServeHTTP
