	if len(regions) > 0 {
		_ = json.Unmarshal(regions, &s.Regions)
	}
	return &s, nil
}

// Recompute computes a new complete version while the previous ready version
// keeps being served. The new version becomes ready only when fully computed.
func (m *SnapshotManager) Recompute(ctx context.Context, networkRevision int) (*Snapshot, error) {
	m.mu.Lock()
	defer m.mu.Unlock()
	// Find the next version number.
	var maxVer int
	_ = m.store.PG.QueryRow(ctx, "SELECT COALESCE(max(version),0) FROM serviceability_snapshots").Scan(&maxVer)
