	row := s.PG.QueryRow(ctx, `SELECT location_id, name, lat, lon, coverage_km, handling_minutes, active,
		fn_collection_point, fn_transfer_point, fn_hub, fn_laboratory FROM locations WHERE location_id=$1`, id)
	return scanLocation(row)
}

