func (s *Store) SetLocationFunctionStatus(ctx context.Context, tx pgx.Tx, id uuid.UUID, fn string, active bool) (LocationFunction, error) {
	col := ""
	switch fn {
	case "collection_point":
		col = "fn_collection_point"
	case "transfer_point":
		col = "fn_transfer_point"
	case "hub":
		col = "fn_hub"
	case "laboratory":
		col = "fn_laboratory"
	}
	if col == "" {
		return LocationFunction{}, ErrInvalid
	}
	_, err := tx.Exec(ctx, "UPDATE locations SET "+col+"=$2 WHERE location_id=$1", id, active)
	if err != nil {
		return LocationFunction{}, err
	}
	var fns LocationFunction
	row := tx.QueryRow(ctx, "SELECT fn_collection_point, fn_transfer_point, fn_hub, fn_laboratory FROM locations WHERE location_id=$1", id)
	if err := row.Scan(&fns.CollectionPoint, &fns.TransferPoint, &fns.Hub, &fns.Laboratory); err != nil {
