	writeData(w, http.StatusOK, map[string]any{
		"locationId": id.String(),
		"function":   req.Function,
		"active":     req.Active,
		"functions":  fnStates(fns),
	})
}

// handleCreateConnection (admin).
func (s *Server) handleCreateConnection(w http.ResponseWriter, r *http.Request) {
	pr := principalFrom(r)
	var req struct {
		FromLocationID string  `json:"fromLocationId"`
		ToLocationID   string  `json:"toLocationId"`
		TravelMinutes  int     `json:"travelMinutes"`
		CostUnits      float64 `json:"costUnits"`
		Cooled         bool    `json:"cooled"`
		Active         bool    `json:"active"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	from, err := uuid.Parse(req.FromLocationID)
	if err != nil {
		writeErr(w, http.StatusBadRequest, "invalid_request", "invalid fromLocationId")
		return
	}
	to, err := uuid.Parse(req.ToLocationID)
	if err != nil {
		writeErr(w, http.StatusBadRequest, "invalid_request", "invalid toLocationId")
		return
	}
	var conn *store.Connection
	err = withTx(r.Context(), s.Store, func(tx pgx.Tx) error {
		c, err := s.Store.CreateConnection(r.Context(), tx, from, to, req.TravelMinutes, req.CostUnits, req.Cooled, req.Active)
		if err != nil {
			return err
		}
		conn = c
		return nil
	})
	if err != nil {
		writeErr(w, http.StatusConflict, "conflict", "could not create connection")
		return
	}
	s.Audit.Record(r.Context(), auditEntry(pr, "create_connection", "connection", conn.ConnectionID.String(), true, ""))
	writeCreated(w, map[string]any{
		"connectionId":   conn.ConnectionID.String(),
		"fromLocationId": conn.FromLocation.String(),
		"toLocationId":   conn.ToLocation.String(),
		"travelMinutes":  conn.TravelMinutes,
		"costUnits":      conn.CostUnits,
		"cooled":         conn.Cooled,
		"active":         conn.Active,
	})
}

// handleSetConnectionStatus (admin).
func (s *Server) handleSetConnectionStatus(w http.ResponseWriter, r *http.Request) {
	pr := principalFrom(r)
	var req struct {
		ConnectionID string `json:"connectionId"`
		Active       bool   `json:"active"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	id, err := uuid.Parse(req.ConnectionID)
	if err != nil {
		writeErr(w, http.StatusBadRequest, "invalid_request", "invalid connectionId")
		return
	}
	err = withTx(r.Context(), s.Store, func(tx pgx.Tx) error {
		return s.Store.SetConnectionStatus(r.Context(), tx, id, req.Active)
	})
	if err != nil {
		writeErr(w, http.StatusNotFound, "not_found", "connection not found")
		return
	}
	s.Audit.Record(r.Context(), auditEntry(pr, "set_connection_status", "connection", id.String(), true, ""))
	writeData(w, http.StatusOK, map[string]any{"connectionId": id.String(), "active": req.Active})
}

// handleCreateSampleType (admin).
func (s *Server) handleCreateSampleType(w http.ResponseWriter, r *http.Request) {
	pr := principalFrom(r)
	var req struct {
		Name                      string   `json:"name"`
		QualifiedCollectorRequired bool     `json:"qualifiedCollectorRequired"`
		RequiredQualification     string   `json:"requiredQualification"`
		ContainerType             string   `json:"containerType"`
		TemperatureMinC           *float64 `json:"temperatureMinC"`
		TemperatureMaxC           *float64 `json:"temperatureMaxC"`
		IncompatibleSampleTypes   []string `json:"incompatibleSampleTypes"`
		RequiresCooledRoute       bool     `json:"requiresCooledRoute"`
		BatchingAllowed           bool     `json:"batchingAllowed"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	if req.Name == "" || req.ContainerType == "" {
		writeErr(w, http.StatusBadRequest, "invalid_request", "name and containerType required")
		return
	}
	incompat, ok := parseIDs(req.IncompatibleSampleTypes)
	if !ok {
		writeErr(w, http.StatusBadRequest, "invalid_request", "invalid incompatibleSampleTypes")
		return
	}
	st := &store.SampleType{
		Name: req.Name, QualifiedCollectorRequired: req.QualifiedCollectorRequired,
		RequiredQualification: req.RequiredQualification, ContainerType: req.ContainerType,
		TemperatureMinC: req.TemperatureMinC, TemperatureMaxC: req.TemperatureMaxC,
		IncompatibleSampleTypes: incompat, RequiresCooledRoute: req.RequiresCooledRoute,
		BatchingAllowed: req.BatchingAllowed,
	}
	err := withTx(r.Context(), s.Store, func(tx pgx.Tx) error {
		return s.Store.CreateSampleType(r.Context(), tx, st)
	})
	if err != nil {
		if isUniqueViolation(err) {
			writeErr(w, http.StatusConflict, "duplicate", "sample type name exists")
			return
		}
		writeErr(w, http.StatusInternalServerError, "internal", "could not create sample type")
		return
	}
	s.Audit.Record(r.Context(), auditEntry(pr, "create_sample_type", "sample_type", st.SampleTypeID.String(), true, "name="+st.Name))
	writeCreated(w, sampleTypeResponse(st))
}

// handleUpdateSampleType (admin).
func (s *Server) handleUpdateSampleType(w http.ResponseWriter, r *http.Request) {
	pr := principalFrom(r)
	var req struct {
		SampleTypeID              string   `json:"sampleTypeId"`
