// handleConfigureLaboratoryAcceptance (admin).
func (s *Server) handleConfigureLaboratoryAcceptance(w http.ResponseWriter, r *http.Request) {
	pr := principalFrom(r)
	var req struct {
		LaboratoryID string `json:"laboratoryId"`
		SampleTypeID string `json:"sampleTypeId"`
		Accepts      bool   `json:"accepts"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	labID, err := uuid.Parse(req.LaboratoryID)
	if err != nil {
		writeErr(w, http.StatusBadRequest, "invalid_request", "invalid laboratoryId")
		return
	}
	stID, err := uuid.Parse(req.SampleTypeID)
	if err != nil {
		writeErr(w, http.StatusBadRequest, "invalid_request", "invalid sampleTypeId")
		return
	}
	var aid uuid.UUID
	err = withTx(r.Context(), s.Store, func(tx pgx.Tx) error {
		id, err := s.Store.ConfigureLabAcceptance(r.Context(), tx, labID, stID, req.Accepts)
		if err != nil {
			return err
		}
		aid = id
		return nil
	})
	if err != nil {
		writeErr(w, http.StatusConflict, "conflict", "could not configure acceptance")
		return
	}
	s.Audit.Record(r.Context(), auditEntry(pr, "configure_laboratory_acceptance", "laboratory", labID.String(), true, ""))
	writeData(w, http.StatusOK, map[string]any{"acceptanceId": aid.String(), "accepts": req.Accepts})
}

// handleConfigureCapacity (admin/dispatcher).
func (s *Server) handleConfigureCapacity(w http.ResponseWriter, r *http.Request) {
	pr := principalFrom(r)
	var req struct {
		ResourceID           string `json:"resourceId"`
		CapacityUnits        int    `json:"capacityUnits"`
		CooledCapacityUnits  int    `json:"cooledCapacityUnits"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	id, err := uuid.Parse(req.ResourceID)
	if err != nil {
		writeErr(w, http.StatusBadRequest, "invalid_request", "invalid resourceId")
		return
	}
	if req.CapacityUnits < 0 {
		req.CapacityUnits = 0
	}
	if req.CooledCapacityUnits < 0 {
		req.CooledCapacityUnits = 0
	}
	var cap *store.Capacity
	err = withTx(r.Context(), s.Store, func(tx pgx.Tx) error {
		c, err := s.Store.ConfigureCapacity(r.Context(), tx, id, req.CapacityUnits, req.CooledCapacityUnits)
		if err != nil {
			return err
		}
		cap = c
		return nil
	})
	if err != nil {
		writeErr(w, http.StatusConflict, "conflict", "could not configure capacity: "+err.Error())
		return
	}
	s.Audit.Record(r.Context(), auditEntry(pr, "configure_capacity", "capacity", id.String(), true, ""))
	writeData(w, http.StatusOK, map[string]any{
		"resourceId":           id.String(),
		"capacityUnits":        req.CapacityUnits,
		"cooledCapacityUnits":  req.CooledCapacityUnits,
	})
	_ = cap
}

